# I'll implement lazygit's core features:
# 1. CLI parsing
# 2. TUI rendering with panels
# 3. Git operations 
# 4. Keybindings
# 5. Configuration

cd /workspace/lazygit-impl

# Let me write the complete implementation
# First, the terminal package
mkdir -p pkg/terminal pkg/config pkg/git pkg/gui pkg/utils

# Terminal package for raw mode and rendering
cat <<'GOEOF' > pkg/terminal/terminal.go
package terminal

import (
	"fmt"
	"os"
	"os/exec"
	"syscall"
	"unsafe"
)

type Termios struct {
	Iflag  uint32
	Oflag  uint32
	Cflag  uint32
	Lflag  uint32
	Cc     [20]uint8
	Ispeed uint32
	Ospeed uint32
}

var originalTermios Termios

func EnableRawMode() error {
	var termios Termios
	if _, _, errno := syscall.Syscall(syscall.SYS_IOCTL,
		uintptr(syscall.Stdin),
		uintptr(syscall.TCGETS),
		uintptr(unsafe.Pointer(&termios))); errno != 0 {
		return fmt.Errorf("ioctl TCGETS: %v", errno)
	}
	originalTermios = termios

	// Raw mode
	termios.Lflag &^= syscall.ECHO | syscall.ICANON | syscall.ISIG | syscall.IEXTEN
	termios.Iflag &^= syscall.IXON | syscall.ICRNL | syscall.BRKINT | syscall.INPCK | syscall.ISTRIP
	termios.Oflag &^= syscall.OPOST
	termios.Cflag |= syscall.CS8
	termios.Cc[syscall.VMIN] = 1
	termios.Cc[syscall.VTIME] = 0

	if _, _, errno := syscall.Syscall(syscall.SYS_IOCTL,
		uintptr(syscall.Stdin),
		uintptr(syscall.TCSETS),
		uintptr(unsafe.Pointer(&termios))); errno != 0 {
		return fmt.Errorf("ioctl TCSETS: %v", errno)
	}
	return nil
}

func DisableRawMode() {
	syscall.Syscall(syscall.SYS_IOCTL,
		uintptr(syscall.Stdin),
		uintptr(syscall.TCSETS),
		uintptr(unsafe.Pointer(&originalTermios)))
}

func GetSize() (int, int, error) {
	type winsize struct {
		Row    uint16
		Col    uint16
		Xpixel uint16
		Ypixel uint16
	}
	ws := &winsize{}
	if _, _, errno := syscall.Syscall(syscall.SYS_IOCTL,
		uintptr(syscall.Stdout),
		uintptr(syscall.TIOCGWINSZ),
		uintptr(unsafe.Pointer(ws))); errno != 0 {
		// Fallback
		cmd := exec.Command("stty", "size")
		cmd.Stdin = os.Stdin
		out, err := cmd.Output()
		if err != nil {
			return 80, 24, nil
		}
		var h, w int
		fmt.Sscanf(string(out), "%d %d", &h, &w)
		return w, h, nil
	}
	return int(ws.Col), int(ws.Row), nil
}

// ANSI escape codes
const (
	ESC = "\x1b"
)

func ClearScreen() string {
	return ESC + "[2J" + ESC + "[H"
}

func MoveTo(x, y int) string {
	return fmt.Sprintf(ESC+"[%d;%dH", y+1, x+1)
}

func HideCursor() string {
	return ESC + "[?25l"
}

func ShowCursor() string {
	return ESC + "[?25h"
}

func EnableMouse() string {
	return ESC + "[?1000h" + ESC + "[?1006h"
}

func DisableMouse() string {
	return ESC + "[?1000l" + ESC + "[?1006l"
}

func AltScreen() string {
	return ESC + "[?1049h"
}

func MainScreen() string {
	return ESC + "[?1049l"
}

// Color codes
const (
	ColorReset   = ESC + "[0m"
	ColorBold    = ESC + "[1m"
	ColorRed     = ESC + "[31m"
	ColorGreen   = ESC + "[32m"
	ColorYellow  = ESC + "[33m"
	ColorBlue    = ESC + "[34m"
	ColorMagenta = ESC + "[35m"
	ColorCyan    = ESC + "[36m"
	ColorWhite   = ESC + "[37m"
	BgBlue       = ESC + "[44m"
)

func Bold(s string) string    { return ColorBold + s + ColorReset }
func Green(s string) string   { return ESC + "[32m" + s + ColorReset }
func BoldGreen(s string) string { return ESC + "[1;32m" + s + ColorReset }
func BoldCyan(s string) string  { return ESC + "[1;36m" + s + ColorReset }
func Red(s string) string     { return ESC + "[31m" + s + ColorReset }
func Blue(s string) string    { return ESC + "[34m" + s + ColorReset }
func Yellow(s string) string  { return ESC + "[33m" + s + ColorReset }
func Cyan(s string) string    { return ESC + "[36m" + s + ColorReset }
func BlueBg(s string) string  { return ESC + "[44m" + s + ColorReset }
func BoldBlueBg(s string) string { return ESC + "[1;44m" + s + ColorReset }
GOEOF

echo "terminal.go created"

