package terminal

import (
	"os"
)

// Key constants
const (
	KeyCtrlC     = 3
	KeyCtrlD     = 4
	KeyCtrlF     = 6
	KeyCtrlL     = 12
	KeyCtrlN     = 14
	KeyCtrlO     = 15
	KeyCtrlP     = 16
	KeyCtrlQ     = 17
	KeyCtrlR     = 18
	KeyCtrlS     = 19
	KeyCtrlT     = 20
	KeyCtrlU     = 21
	KeyCtrlW     = 23
	KeyCtrlY     = 25
	KeyCtrlZ     = 26
	KeyEsc       = 27
	KeySpace     = 32
	KeyBackspace = 127
	KeyEnter     = 13
	KeyTab       = 9
	KeyBackTab   = 0 // special

	// Special keys
	KeyUp    = 1000 + iota
	KeyDown
	KeyLeft
	KeyRight
	KeyHome
	KeyEnd
	KeyPageUp
	KeyPageDown
	KeyDelete
	KeyInsert
	KeyF1
	KeyF2
	KeyF3
	KeyF4
	KeyF5
	KeyF6
	KeyF7
	KeyF8
	KeyF9
	KeyF10
	KeyF11
	KeyF12
	KeyShiftUp
	KeyShiftDown
	KeyAltEnter
	KeyCtrlJ
	KeyCtrlK
	KeyCtrlE
	KeyMouse
)

type Event struct {
	Type    int
	Key     int
	Rune    rune
	MouseX  int
	MouseY  int
	MouseBtn int
}

const (
	EventKey   = 1
	EventMouse = 2
	EventResize = 3
)

func ReadEvent() Event {
	buf := make([]byte, 32)
	n, err := os.Stdin.Read(buf[:1])
	if err != nil || n == 0 {
		return Event{Type: EventKey, Key: KeyCtrlC}
	}

	b := buf[0]

	// Check for ESC sequences
	if b == KeyEsc {
		// Try to read more bytes with a short timeout
		n2, _ := readWithTimeout(buf[1:], 50)
		if n2 == 0 {
			return Event{Type: EventKey, Key: KeyEsc}
		}

		seq := buf[1 : 1+n2]

		// Mouse event: ESC[<...M or ESC[<...m
		if len(seq) > 0 && seq[0] == '[' && len(seq) > 1 {
			switch seq[1] {
			case 'A':
				return Event{Type: EventKey, Key: KeyUp}
			case 'B':
				return Event{Type: EventKey, Key: KeyDown}
			case 'C':
				return Event{Type: EventKey, Key: KeyRight}
			case 'D':
				return Event{Type: EventKey, Key: KeyLeft}
			case 'H':
				return Event{Type: EventKey, Key: KeyHome}
			case 'F':
				return Event{Type: EventKey, Key: KeyEnd}
			case '5':
				if len(seq) > 2 && seq[2] == '~' {
					return Event{Type: EventKey, Key: KeyPageUp}
				}
			case '6':
				if len(seq) > 2 && seq[2] == '~' {
					return Event{Type: EventKey, Key: KeyPageDown}
				}
			case '3':
				if len(seq) > 2 && seq[2] == '~' {
					return Event{Type: EventKey, Key: KeyDelete}
				}
			case '1':
				if len(seq) > 2 {
					switch seq[2] {
					case '~':
						return Event{Type: EventKey, Key: KeyHome}
					case ';':
						// ESC[1;2A = shift+up, etc.
						if len(seq) > 3 && seq[3] == '2' {
							if len(seq) > 4 {
								switch seq[4] {
								case 'A':
									return Event{Type: EventKey, Key: KeyShiftUp}
								case 'B':
									return Event{Type: EventKey, Key: KeyShiftDown}
								}
							}
						}
					}
				}
			case '2':
				if len(seq) > 2 && seq[2] == '~' {
					return Event{Type: EventKey, Key: KeyInsert}
				}
			case '4':
				if len(seq) > 2 && seq[2] == '~' {
					return Event{Type: EventKey, Key: KeyEnd}
				}
			case '<':
				// SGR mouse: ESC[<btn;x;yM or m
				// Parse mouse event
				return parseMouseSGR(seq[2:])
			}
			// Check for O sequences
		} else if len(seq) > 0 && seq[0] == 'O' {
			if len(seq) > 1 {
				switch seq[1] {
				case 'A':
					return Event{Type: EventKey, Key: KeyUp}
				case 'B':
					return Event{Type: EventKey, Key: KeyDown}
				case 'C':
					return Event{Type: EventKey, Key: KeyRight}
				case 'D':
					return Event{Type: EventKey, Key: KeyLeft}
				case 'H':
					return Event{Type: EventKey, Key: KeyHome}
				case 'F':
					return Event{Type: EventKey, Key: KeyEnd}
				}
			}
		} else if len(seq) > 0 && seq[0] == '\r' {
			return Event{Type: EventKey, Key: KeyAltEnter}
		} else if len(seq) > 0 {
			// Alt key combinations
			_ = seq
		}
