package git

import (
	"bytes"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"time"
)

type Repo struct {
	WorkTree string
	GitDir   string
}

type FileStatus struct {
	Name     string
	X        byte // staged status
	Y        byte // unstaged status
	IsNew    bool
	IsDir    bool
	Children []*FileStatus
}

type Commit struct {
	Hash       string
	ShortHash  string
	Author     string
	AuthorInitials string
	Date       time.Time
	Subject    string
	IsMerge    bool
}

type Branch struct {
	Name      string
	Current   bool
	Upstream  string
	AheadBy   int
	BehindBy  int
	Hash      string
}

type StashEntry struct {
	Index   int
	Name    string
}

// FindGitRepo finds the git repo from the given path
func FindGitRepo(path string) (*Repo, error) {
	if path == "" {
		var err error
		path, err = os.Getwd()
		if err != nil {
			return nil, err
		}
	}

	// Check if path is inside a git repo
	cmd := exec.Command("git", "-C", path, "rev-parse", "--show-toplevel")
	out, err := cmd.Output()
	if err != nil {
		return nil, fmt.Errorf("not a git repository")
	}
	workTree := strings.TrimSpace(string(out))

	cmd2 := exec.Command("git", "-C", path, "rev-parse", "--git-dir")
	out2, err := cmd2.Output()
	if err != nil {
		return nil, err
	}
	gitDir := strings.TrimSpace(string(out2))
	if !filepath.IsAbs(gitDir) {
		gitDir = filepath.Join(workTree, gitDir)
	}

	return &Repo{WorkTree: workTree, GitDir: gitDir}, nil
}

func (r *Repo) RepoName() string {
	return filepath.Base(r.WorkTree)
}

func (r *Repo) run(args ...string) (string, error) {
	cmd := exec.Command("git", append([]string{"--work-tree", r.WorkTree, "--git-dir", r.GitDir}, args...)...)
	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr
	err := cmd.Run()
	if err != nil {
		return "", fmt.Errorf("%s: %s", err, stderr.String())
	}
	return stdout.String(), nil
}

func (r *Repo) runWith(env []string, args ...string) (string, error) {
	cmd := exec.Command("git", append([]string{"--work-tree", r.WorkTree, "--git-dir", r.GitDir}, args...)...)
	cmd.Env = append(os.Environ(), env...)
	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr
	err := cmd.Run()
	if err != nil {
		return "", fmt.Errorf("%s: %s", err, stderr.String())
	}
	return stdout.String(), nil
}

// GetCurrentBranch returns the current branch name
func (r *Repo) GetCurrentBranch() (string, error) {
	out, err := r.run("symbolic-ref", "--short", "HEAD")
	if err != nil {
		// Might be detached HEAD
		out2, err2 := r.run("rev-parse", "--short", "HEAD")
		if err2 != nil {
			return "HEAD", nil
		}
		return "HEAD (" + strings.TrimSpace(out2) + ")", nil
	}
	return strings.TrimSpace(out), nil
}

// GetStatus returns file status
func (r *Repo) GetStatus() ([]*FileStatus, error) {
	out, err := r.run("status", "--porcelain", "-u")
	if err != nil {
		return nil, err
	}

	var files []*FileStatus
	for _, line := range strings.Split(out, "\n") {
		if len(line) < 3 {
			continue
		}
		x := line[0]
		y := line[1]
		name := line[3:]
		// Handle rename: old -> new
		if strings.Contains(name, " -> ") {
			parts := strings.SplitN(name, " -> ", 2)
			name = parts[1]
		}
		files = append(files, &FileStatus{
			Name: name,
			X:    x,
			Y:    y,
		})
	}
	return files, nil
}

// GetBranches returns branches
func (r *Repo) GetBranches() ([]*Branch, error) {
	out, err := r.run("branch", "-vv", "--sort=-committerdate")
	if err != nil {
		return nil, err
	}

	var branches []*Branch
	for _, line := range strings.Split(out, "\n") {
		if len(line) < 3 {
			continue
		}
		current := line[0] == '*'
		rest := strings.TrimSpace(line[2:])
		parts := strings.Fields(rest)
		if len(parts) < 2 {
			continue
		}
		name := parts[0]
		hash := parts[1]

		b := &Branch{
			Name:    name,
			Current: current,
			Hash:    hash,
		}

		// Parse ahead/behind from upstream info like [origin/main: ahead 2, behind 3]
		for _, p := range parts[2:] {
			if strings.HasPrefix(p, "[") {
				info := strings.Trim(p, "[]:")
				_ = info
			}
		}

		branches = append(branches, b)
	}
	return branches, nil
}

// GetCommits returns commit log
func (r *Repo) GetCommits(maxCount int) ([]*Commit, error) {
	format := "%H%x00%h%x00%an%x00%ae%x00%ad%x00%s"
	args := []string{"log", "--date=unix", fmt.Sprintf("--format=%s", format)}
	if maxCount > 0 {
		args = append(args, fmt.Sprintf("-n%d", maxCount))
	}

	out, err := r.run(args...)
	if err != nil {
		return nil, err
	}

	var commits []*Commit
	for _, line := range strings.Split(out, "\n") {
		if line == "" {
			continue
		}
		parts := strings.Split(line, "\x00")
		if len(parts) < 6 {
			continue
		}

		var t time.Time
		var unixTime int64
		fmt.Sscanf(parts[4], "%d", &unixTime)
		if unixTime > 0 {
			t = time.Unix(unixTime, 0)
		}

		author := parts[2]
		initials := authorInitials(author)

		commits = append(commits, &Commit{
			Hash:           parts[0],
			ShortHash:      parts[1],
			Author:         author,
			AuthorInitials: initials,
			Date:           t,
			Subject:        parts[5],
		})
	}
	return commits, nil
}

func authorInitials(name string) string {
	parts := strings.Fields(name)
	if len(parts) == 0 {
		return "?"
	}
	if len(parts) == 1 {
		if len(parts[0]) >= 2 {
			return strings.ToUpper(parts[0][:2])
		}
		return strings.ToUpper(parts[0])
	}
	return strings.ToUpper(string(parts[0][0])) + strings.ToUpper(string(parts[len(parts)-1][0]))
}

// GetStash returns stash entries
func (r *Repo) GetStash() ([]*StashEntry, error) {
	out, err := r.run("stash", "list", "--format=%i %s")
	if err != nil {
		return nil, nil
	}

	var entries []*StashEntry
	for i, line := range strings.Split(out, "\n") {
		if line == "" {
			continue
		}
		entries = append(entries, &StashEntry{
			Index: i,
			Name:  line,
		})
	}
	return entries, nil
}

// GetFileDiff returns diff for a file
func (r *Repo) GetFileDiff(file string, staged bool) (string, error) {
	var args []string
	if staged {
		args = []string{"diff", "--cached", "--", file}
	} else {
		args = []string{"diff", "--", file}
	}
	out, err := r.run(args...)
	if err != nil {
		return "", err
	}
	return out, nil
}

// GetUntrackedFileDiff returns content of untracked file
func (r *Repo) GetUntrackedFileDiff(file string) (string, error) {
	content, err := os.ReadFile(filepath.Join(r.WorkTree, file))
	if err != nil {
		return "", err
	}
	return string(content), nil
}

// StageFile stages a file
func (r *Repo) StageFile(file string) error {
	_, err := r.run("add", "--", file)
	return err
}

// UnstageFile unstages a file
func (r *Repo) UnstageFile(file string) error {
	_, err := r.run("reset", "HEAD", "--", file)
	return err
}

// GetCommitDiff returns the diff for a commit
func (r *Repo) GetCommitDiff(hash string) (string, error) {
	return r.run("show", hash)
}

// GetBranchLog returns the log graph for a branch
func (r *Repo) GetBranchLog(branch string) (string, error) {
	return r.run("log", "--oneline", "--decorate", "--color", branch)
}

// HasRemote checks if there are remotes
func (r *Repo) HasRemote() bool {
	out, err := r.run("remote")
	return err == nil && strings.TrimSpace(out) != ""
}

// GetRemoteName returns the first remote name
func (r *Repo) GetRemoteName() string {
	out, err := r.run("remote")
	if err != nil {
		return ""
	}
	lines := strings.Split(strings.TrimSpace(out), "\n")
	if len(lines) > 0 {
		return lines[0]
	}
	return ""
}
