func (s *Screen) DrawBorder(x, y, w, h int, style string, title string, footer string) {
	// Top border
	s.SetCell(x, y, BoxTopLeft, style)
	titleLen := utf8.RuneCountInString(title)
	if w > 2 {
		// Fill the top line
		topContent := w - 2
		drawn := 0
		if title != "" {
			// Draw title: ─title─
			titleStr := "─" + title + "─"
			s.WriteString(x+1, y, titleStr, style)
			drawn = StringWidth(titleStr)
		}
		for i := drawn; i < topContent; i++ {
			s.SetCell(x+1+i, y, BoxHoriz, style)
		}
		_ = titleLen
	}
	s.SetCell(x+w-1, y, BoxTopRight, style)

	// Side borders
	for i := 1; i < h-1; i++ {
		s.SetCell(x, y+i, BoxVert, style)
		s.SetCell(x+w-1, y+i, BoxVert, style)
	}

	// Bottom border
	s.SetCell(x, y+h-1, BoxBottomLeft, style)
	if footer != "" {
		footerStr := "─" + footer + "─"
		fw := StringWidth(footerStr)
		startX := x + w - 1 - fw - 1
		if startX < x+1 {
			startX = x + 1
		}
		for i := x + 1; i < startX; i++ {
			s.SetCell(i, y+h-1, BoxHoriz, style)
		}
		s.WriteString(startX, y+h-1, footerStr, style)
		endX := startX + fw
		for i := endX; i < x+w-1; i++ {
			s.SetCell(i, y+h-1, BoxHoriz, style)
		}
	} else {
		for i := x + 1; i < x+w-1; i++ {
			s.SetCell(i, y+h-1, BoxHoriz, style)
		}
	}
	s.SetCell(x+w-1, y+h-1, BoxBottomRight, style)
}

// DrawBorderWithTitle draws a border with a stylized title [num]─Name
func (s *Screen) DrawBorderWithTitle(x, y, w, h int, borderStyle string, titleParts []TitlePart, footer string) {
	// Top border
	s.SetCell(x, y, BoxTopLeft, borderStyle)

	// Build title string
	col := x + 1
	for _, part := range titleParts {
		for _, r := range part.Text {
			if col >= x+w-1 {
				break
			}
			s.SetCell(col, y, r, part.Style)
			col++
		}
	}
	// Fill remaining with horizontal lines
	for ; col < x+w-1; col++ {
		s.SetCell(col, y, BoxHoriz, borderStyle)
	}
	s.SetCell(x+w-1, y, BoxTopRight, borderStyle)

	// Side borders
	for i := 1; i < h-1; i++ {
		s.SetCell(x, y+i, BoxVert, borderStyle)
		s.SetCell(x+w-1, y+i, BoxVert, borderStyle)
	}

	// Bottom border
	s.SetCell(x, y+h-1, BoxBottomLeft, borderStyle)
	if footer != "" {
		footerStr := footer + "─"
		fw := StringWidth(footerStr)
		startX := x + w - 1 - fw - 1
		if startX < x+1 {
			startX = x + 1
		}
		for i := x + 1; i < startX; i++ {
			s.SetCell(i, y+h-1, BoxHoriz, borderStyle)
		}
		s.WriteString(startX, y+h-1, footerStr, borderStyle)
		endX := startX + fw
		for i := endX; i < x+w-1; i++ {
			s.SetCell(i, y+h-1, BoxHoriz, borderStyle)
		}
	} else {
		for i := x + 1; i < x+w-1; i++ {
			s.SetCell(i, y+h-1, BoxHoriz, borderStyle)
		}
	}
	s.SetCell(x+w-1, y+h-1, BoxBottomRight, borderStyle)
}

type TitlePart struct {
	Text  string
	Style string
}

// Sprintf with reset
func Styled(style, s string) string {
	return style + s + Reset
}

// IsControlChar checks if rune is a control character
func IsControlChar(r rune) bool {
	return unicode.IsControl(r) && r != '\n' && r != '\r' && r != '\t'
}

// WrapText wraps text to width
func WrapText(text string, width int) []string {
	if width <= 0 {
		return []string{text}
	}
	var lines []string
	for _, line := range strings.Split(text, "\n") {
		if StringWidth(line) <= width {
			lines = append(lines, line)
			continue
		}
		// Wrap
		current := ""
		currentW := 0
		for _, r := range line {
			rw := runeWidth(r)
			if currentW+rw > width {
				lines = append(lines, current)
				current = string(r)
				currentW = rw
			} else {
				current += string(r)
				currentW += rw
			}
		}
		if current != "" {
			lines = append(lines, current)
		}
	}
	return lines
}

// ColorizeGitDiff applies colors to git diff output
func ColorizeGitDiff(line string) string {
	if len(line) == 0 {
		return ""
	}
	switch {
	case strings.HasPrefix(line, "+++"):
		return FgGreen + line + Reset
	case strings.HasPrefix(line, "---"):
		return FgRed + line + Reset
	case strings.HasPrefix(line, "+"):
		return FgGreen + line + Reset
	case strings.HasPrefix(line, "-"):
		return FgRed + line + Reset
	case strings.HasPrefix(line, "@@"):
		return FgCyan + line + Reset
	case strings.HasPrefix(line, "diff"):
		return Bold + line + Reset
	case strings.HasPrefix(line, "index"):
		return Dim + line + Reset
	default:
		return line
	}
}

// FormatFileStatus formats the two-letter git status code for display
func FormatFileStatus(x, y byte) string {
	return fmt.Sprintf("%c%c", x, y)
}
