func (g *GUI) Run() error {
	// Setup terminal
	if err := terminal.EnableRawMode(); err != nil {
		return err
	}
	defer terminal.DisableRawMode()

	// Get terminal size
	w, h, err := terminal.GetSize()
	if err != nil || w == 0 {
		w, h = 80, 24
	}
	g.width = w
	g.height = h
	g.screen = NewScreen(w, h)

	// Enter alt screen
	fmt.Fprint(os.Stdout, terminal.AltScreen())
	fmt.Fprint(os.Stdout, terminal.HideCursor())
	fmt.Fprint(os.Stdout, terminal.EnableMouse())

	defer func() {
		fmt.Fprint(os.Stdout, terminal.DisableMouse())
		fmt.Fprint(os.Stdout, terminal.ShowCursor())
		fmt.Fprint(os.Stdout, terminal.MainScreen())
	}()

	// Load initial data
	if err := g.refresh(); err != nil {
		return err
	}

	// Add random tip to command log
	g.addCommandLog("Random tip: " + g.randomTip)
	g.addCommandLog("")

	g.running = true

	// Initial render
	g.render()

	// Event loop
	for g.running {
		evt := terminal.ReadEvent()
		g.handleEvent(evt)
		if g.dirty {
			g.render()
			g.dirty = false
		}
	}

	return nil
}

func (g *GUI) refresh() error {
	var err error

	g.files, err = g.repo.GetStatus()
	if err != nil {
		g.files = nil
	}

	g.branches, err = g.repo.GetBranches()
	if err != nil {
		g.branches = nil
	}

	g.commits, err = g.repo.GetCommits(100)
	if err != nil {
		g.commits = nil
	}

	g.stash, err = g.repo.GetStash()
	if err != nil {
		g.stash = nil
	}

	// Update main content
	g.updateMainContent()

	g.dirty = true
	return nil
}

func (g *GUI) addCommandLog(msg string) {
	g.commandLog = append(g.commandLog, msg)
	// Keep only last N entries
	maxEntries := 20
	if len(g.commandLog) > maxEntries {
		g.commandLog = g.commandLog[len(g.commandLog)-maxEntries:]
	}
}

func (g *GUI) updateMainContent() {
	g.mainContent = nil
	g.mainOffset = 0

	switch g.focusedPanel {
	case PanelFiles:
		g.updateMainContentForFiles()
	case PanelBranches:
		g.updateMainContentForBranches()
	case PanelCommits:
		g.updateMainContentForCommits()
	case PanelStash:
		// nothing
	case PanelStatus:
		// nothing
	}
}

func (g *GUI) updateMainContentForFiles() {
	if len(g.files) == 0 {
		g.mainContent = []string{"No changes"}
		return
	}

	idx := g.fileIdx
	if idx >= len(g.files) {
		idx = len(g.files) - 1
	}
	if idx < 0 {
		return
	}

	file := g.files[idx]

	// Get diff
	var content string
	var err error

	if file.X == '?' && file.Y == '?' {
		// Untracked file
		content, err = g.repo.GetUntrackedFileDiff(file.Name)
		if err != nil {
			content = fmt.Sprintf("Error reading file: %v", err)
		}
	} else {
		// Check if staged or unstaged
		if file.Y != ' ' && file.Y != '.' {
			content, err = g.repo.GetFileDiff(file.Name, false)
		} else {
			content, err = g.repo.GetFileDiff(file.Name, true)
		}
		if err != nil || content == "" {
			// Try the other way
			if file.X != ' ' && file.X != '.' {
				content, err = g.repo.GetFileDiff(file.Name, true)
			}
		}
		if err != nil {
			content = fmt.Sprintf("Error: %v", err)
		}
	}

	lines := strings.Split(content, "\n")
	g.mainContent = lines
}

func (g *GUI) updateMainContentForBranches() {
	if len(g.branches) == 0 {
		return
	}
	idx := g.branchIdx
	if idx >= len(g.branches) {
		idx = len(g.branches) - 1
	}
	if idx < 0 {
		return
	}
	b := g.branches[idx]
	content, err := g.repo.GetBranchLog(b.Name)
	if err != nil {
		g.mainContent = []string{fmt.Sprintf("Error: %v", err)}
		return
	}
	g.mainContent = strings.Split(content, "\n")
}

func (g *GUI) updateMainContentForCommits() {
	if len(g.commits) == 0 {
		return
	}
	idx := g.commitIdx
	if idx >= len(g.commits) {
		idx = len(g.commits) - 1
	}
	if idx < 0 {
		return
	}
	c := g.commits[idx]
	content, err := g.repo.GetCommitDiff(c.Hash)
	if err != nil {
		g.mainContent = []string{fmt.Sprintf("Error: %v", err)}
		return
	}
	g.mainContent = strings.Split(content, "\n")
}

func (g *GUI) render() {
	g.screen.Clear()

	// Calculate layout
	sideWidth := g.width / 3
	if sideWidth < 20 {
		sideWidth = 20
	}
	mainWidth := g.width - sideWidth

	// Heights for left panel sections
	// Status: 3 rows
	// Files: dynamic
	// Branches: dynamic
	// Commits: dynamic
	// Stash: 4 rows
	// CommandLog: 7 rows (in main area)

	statusH := 3
	stashH := 4
	commandLogH := 7

	remaining := g.height - 1 - statusH - stashH // 1 for bottom bar
	if remaining < 10 {
		remaining = 10
	}

	// Distribute remaining: files, branches, commits each get 1/3
	filesH := remaining / 3
	if filesH < 3 {
		filesH = 3
	}
	branchesH := remaining / 3
	if branchesH < 3 {
		branchesH = 3
	}
	commitsH := remaining - filesH - branchesH
	if commitsH < 3 {
		commitsH = 3
	}

	mainH := g.height - 1 - commandLogH
	if mainH < 5 {
		mainH = 5
	}

	// Y positions
	statusY := 0
	filesY := statusY + statusH
	branchesY := filesY + filesH
	commitsY := branchesY + branchesH
	stashY := commitsY + commitsH
	mainY := 0
	commandLogY := mainH

	// Draw panels
	g.drawStatus(0, statusY, sideWidth, statusH)
	g.drawFiles(0, filesY, sideWidth, filesH)
	g.drawBranches(0, branchesY, sideWidth, branchesH)
	g.drawCommits(0, commitsY, sideWidth, commitsH)
	g.drawStash(0, stashY, sideWidth, stashH)
	g.drawMain(sideWidth, mainY, mainWidth, mainH)
	g.drawCommandLog(sideWidth, commandLogY, mainWidth, commandLogH)

	// Bottom bar
	g.drawBottomBar(0, g.height-1, g.width)

	// Draw popups on top
	if g.showWelcome && !g.popupDismissed {
		g.drawWelcomePopup()
	}

	if g.showInput {
		g.drawInputPrompt()
	}

	if g.showConfirm {
		g.drawConfirmDialog()
	}

	// Flush to stdout
	out := g.screen.Render()
	fmt.Fprint(os.Stdout, out)
}

