func (g *GUI) handleFilesKey(evt terminal.Event) {
	switch evt.Key {
	case terminal.KeyUp:
		if g.fileIdx > 0 {
			g.fileIdx--
			g.updateMainContent()
			g.dirty = true
		}
	case terminal.KeyDown:
		if g.fileIdx < len(g.files)-1 {
			g.fileIdx++
			g.updateMainContent()
			g.dirty = true
		}
	case terminal.KeyEnter:
		// Go into staging view
		g.dirty = true
	}

	switch evt.Rune {
	case 'j':
		if g.fileIdx < len(g.files)-1 {
			g.fileIdx++
			g.updateMainContent()
			g.dirty = true
		}
	case 'k':
		if g.fileIdx > 0 {
			g.fileIdx--
			g.updateMainContent()
			g.dirty = true
		}
	case ' ':
		// Stage/unstage file
		if g.fileIdx < len(g.files) {
			f := g.files[g.fileIdx]
			var err error
			if f.X == '?' || f.Y != ' ' {
				err = g.repo.StageFile(f.Name)
				g.addCommandLog(fmt.Sprintf("git add -- %s", f.Name))
			} else {
				err = g.repo.UnstageFile(f.Name)
				g.addCommandLog(fmt.Sprintf("git reset HEAD -- %s", f.Name))
			}
			if err != nil {
				g.addCommandLog(fmt.Sprintf("Error: %v", err))
			}
			g.refresh()
		}
	case 'c':
		// Commit
		g.promptCommit()
	case 'a':
		// Stage all
		_, err := g.repo.RunCommand("add", "-A")
		if err != nil {
			g.addCommandLog(fmt.Sprintf("Error: %v", err))
		} else {
			g.addCommandLog("git add -A")
			g.refresh()
		}
	case 'd':
		// Discard changes
		if g.fileIdx < len(g.files) {
			f := g.files[g.fileIdx]
			g.showConfirmDialog(
				fmt.Sprintf("Discard changes to %s?", f.Name),
				func() {
					g.repo.RunCommand("checkout", "--", f.Name)
					g.addCommandLog(fmt.Sprintf("git checkout -- %s", f.Name))
					g.refresh()
				},
				nil,
			)
		}
	case 'r':
		g.refresh()
	case ']':
		g.filesTab = (g.filesTab + 1) % 3
		g.dirty = true
	case '[':
		g.filesTab = (g.filesTab + 2) % 3
		g.dirty = true
	}
}

func (g *GUI) handleBranchesKey(evt terminal.Event) {
	switch evt.Key {
	case terminal.KeyUp:
		if g.branchIdx > 0 {
			g.branchIdx--
			g.updateMainContent()
			g.dirty = true
		}
	case terminal.KeyDown:
		if g.branchIdx < len(g.branches)-1 {
			g.branchIdx++
			g.updateMainContent()
			g.dirty = true
		}
	}

	switch evt.Rune {
	case 'j':
		if g.branchIdx < len(g.branches)-1 {
			g.branchIdx++
			g.updateMainContent()
			g.dirty = true
		}
	case 'k':
		if g.branchIdx > 0 {
			g.branchIdx--
			g.updateMainContent()
			g.dirty = true
		}
	case ' ':
		// Checkout branch
		if g.branchIdx < len(g.branches) {
			b := g.branches[g.branchIdx]
			g.repo.RunCommand("checkout", b.Name)
			g.addCommandLog(fmt.Sprintf("git checkout %s", b.Name))
			g.refresh()
		}
	case 'n':
		// New branch
		g.promptInput("New branch name", "", func(name string) {
			if name != "" {
				g.repo.RunCommand("checkout", "-b", name)
				g.addCommandLog(fmt.Sprintf("git checkout -b %s", name))
				g.refresh()
			}
		})
	case ']':
		g.branchesTab = (g.branchesTab + 1) % 3
		g.dirty = true
	case '[':
		g.branchesTab = (g.branchesTab + 2) % 3
		g.dirty = true
	}
}

