		g.showConfirm = false
		if g.confirmYes != nil {
			g.confirmYes()
		}
		g.dirty = true
	case 'n', 'N':
		g.showConfirm = false
		if g.confirmNo != nil {
			g.confirmNo()
		}
		g.dirty = true
	}

	switch evt.Key {
	case terminal.KeyEsc:
		g.showConfirm = false
		if g.confirmNo != nil {
