	}
	idx := g.commitIdx
	if idx >= len(g.commits) {
		idx = len(g.commits) - 1
	}
	if idx < 0 {
		return
	}
	c := g.commits[idx]
	content, err := g.repo.GetCommitDiff(c.Hash)
	if err != nil {
		g.mainContent = []string{fmt.Sprintf("Error: %v", err)}
		return
	}
	g.mainContent = strings.Split(content, "\n")
}

func (g *GUI) render() {
	g.screen.Clear()

	// Calculate layout
	sideWidth := g.width / 3
	if sideWidth < 20 {
		sideWidth = 20
	}
	mainWidth := g.width - sideWidth

	// Heights for left panel sections
	// Status: 3 rows
	// Files: dynamic
	// Branches: dynamic
	// Commits: dynamic
	// Stash: 4 rows
	// CommandLog: 7 rows (in main area)

	statusH := 3
	stashH := 4
	commandLogH := 7

	remaining := g.height - 1 - statusH - stashH // 1 for bottom bar
	if remaining < 10 {
		remaining = 10
	}

	// Distribute remaining: files, branches, commits each get 1/3
	filesH := remaining / 3
	if filesH < 3 {
		filesH = 3
	}
	branchesH := remaining / 3
	if branchesH < 3 {
		branchesH = 3
	}
	commitsH := remaining - filesH - branchesH
	if commitsH < 3 {
		commitsH = 3
	}

	mainH := g.height - 1 - commandLogH
	if mainH < 5 {
		mainH = 5
	}

	// Y positions
	statusY := 0
	filesY := statusY + statusH
	branchesY := filesY + filesH
	commitsY := branchesY + branchesH
	stashY := commitsY + commitsH
	mainY := 0
	commandLogY := mainH

	// Draw panels
	g.drawStatus(0, statusY, sideWidth, statusH)
	g.drawFiles(0, filesY, sideWidth, filesH)
	g.drawBranches(0, branchesY, sideWidth, branchesH)
	g.drawCommits(0, commitsY, sideWidth, commitsH)
	g.drawStash(0, stashY, sideWidth, stashH)
	g.drawMain(sideWidth, mainY, mainWidth, mainH)
	g.drawCommandLog(sideWidth, commandLogY, mainWidth, commandLogH)

	// Bottom bar
	g.drawBottomBar(0, g.height-1, g.width)

	// Draw popups on top
	if g.showWelcome && !g.popupDismissed {
		g.drawWelcomePopup()
	}

	if g.showInput {
		g.drawInputPrompt()
	}

	if g.showConfirm {
		g.drawConfirmDialog()
	}

	// Flush to stdout
	out := g.screen.Render()
	fmt.Fprint(os.Stdout, out)
}

