	lines := strings.Split(g.confirmMsg, "\n")
	maxW := 60
	for _, l := range lines {
		if StringWidth(l) > maxW {
			maxW = StringWidth(l)
		}
	}
	if maxW > g.width-4 {
		maxW = g.width - 4
	}

	dialogW := maxW + 4
	dialogH := len(lines) + 4
	dialogX := (g.width - dialogW) / 2
	dialogY := (g.height - dialogH) / 2

	borderStyle := Bold + FgCyan
	g.screen.DrawBorder(dialogX, dialogY, dialogW, dialogH, borderStyle, "", "")
	for i := 1; i < dialogH-1; i++ {
		g.screen.FillLine(dialogX+1, dialogY+i, dialogW-2, "")
	}

	for i, line := range lines {
		g.screen.WriteString(dialogX+2, dialogY+1+i, TruncateString(line, dialogW-4), FgDefault)
	}

	// Yes/No buttons
	buttonRow := dialogY + dialogH - 2
	g.screen.WriteString(dialogX+2, buttonRow, "(y) Yes   (n) No", FgDefault)
}

// handleEvent processes a terminal event
func (g *GUI) handleEvent(evt terminal.Event) {
	if evt.Type == terminal.EventResize {
		w, h, _ := terminal.GetSize()
		if w > 0 && h > 0 {
			g.width = w
			g.height = h
			g.screen = NewScreen(w, h)
		}
		g.dirty = true
		return
	}

	if evt.Type != terminal.EventKey {
		if evt.Type == terminal.EventMouse {
			g.handleMouse(evt)
		}
		return
	}

	// Handle popups first
	if g.showWelcome && !g.popupDismissed {
		switch evt.Key {
		case terminal.KeyEnter, terminal.KeyEsc:
			g.popupDismissed = true
			g.dirty = true
		}
		return
	}

	if g.showInput {
		g.handleInputKey(evt)
		return
	}

	if g.showConfirm {
		g.handleConfirmKey(evt)
		return
	}

	if g.searching {
		g.handleSearchKey(evt)
		return
	}

	// Global keybindings
	switch evt.Key {
	case terminal.KeyCtrlC:
		g.running = false
		return
	case terminal.KeyCtrlZ:
		// Suspend
		terminal.DisableRawMode()
		// Send SIGSTOP
		p, _ := os.FindProcess(os.Getpid())
		p.Signal(os.Signal(nil))
		terminal.EnableRawMode()
		g.dirty = true
		return
	}

	switch evt.Rune {
	case 'q':
		g.running = false
		return
	case 'Q':
		g.running = false
		return
	case 'R':
		g.refresh()
		g.addCommandLog("git status, git branch, git log ...")
		g.dirty = true
		return
	case '@':
		// Toggle command log visibility or focus
		g.dirty = true
		return
	case '?':
		g.showKeybindingsHelp()
		return
	}

	// Panel navigation
	switch evt.Key {
	case terminal.KeyTab:
		g.focusedPanel = (g.focusedPanel + 1) % 5
		g.updateMainContent()
		g.dirty = true
		return
	case terminal.KeyBackTab:
		g.focusedPanel = (g.focusedPanel + 4) % 5
		g.updateMainContent()
		g.dirty = true
		return
	}

	// Jump to panel by number
	switch evt.Rune {
	case '1':
		g.focusedPanel = PanelStatus
		g.updateMainContent()
		g.dirty = true
		return
	case '2':
		g.focusedPanel = PanelFiles
		g.updateMainContent()
		g.dirty = true
		return
	case '3':
		g.focusedPanel = PanelBranches
		g.updateMainContent()
		g.dirty = true
		return
	case '4':
		g.focusedPanel = PanelCommits
		g.updateMainContent()
		g.dirty = true
		return
	case '5':
		g.focusedPanel = PanelStash
		g.updateMainContent()
		g.dirty = true
		return
	case '0':
		g.focusedPanel = PanelMain
		g.dirty = true
		return
	}

	// Main view scrolling (global)
	switch evt.Key {
	case terminal.KeyPageUp:
		if g.mainOffset > 0 {
			g.mainOffset -= 10
			if g.mainOffset < 0 {
				g.mainOffset = 0
			}
			g.dirty = true
		}
		return
	case terminal.KeyPageDown:
		g.mainOffset += 10
		maxOff := len(g.mainContent) - 5
		if maxOff < 0 {
			maxOff = 0
		}
		if g.mainOffset > maxOff {
			g.mainOffset = maxOff
		}
		g.dirty = true
		return
	}

	// Panel-specific keys
	switch g.focusedPanel {
	case PanelStatus:
		g.handleStatusKey(evt)
	case PanelFiles:
		g.handleFilesKey(evt)
	case PanelBranches:
		g.handleBranchesKey(evt)
	case PanelCommits:
		g.handleCommitsKey(evt)
	case PanelStash:
		g.handleStashKey(evt)
	case PanelMain:
		g.handleMainKey(evt)
	}
}

