	g.commandLog = append(g.commandLog, msg)
	// Keep only last N entries
	maxEntries := 20
	if len(g.commandLog) > maxEntries {
		g.commandLog = g.commandLog[len(g.commandLog)-maxEntries:]
	}
}

func (g *GUI) updateMainContent() {
	g.mainContent = nil
	g.mainOffset = 0

	switch g.focusedPanel {
	case PanelFiles:
		g.updateMainContentForFiles()
	case PanelBranches:
		g.updateMainContentForBranches()
	case PanelCommits:
		g.updateMainContentForCommits()
	case PanelStash:
		// nothing
	case PanelStatus:
		// nothing
	}
}

func (g *GUI) updateMainContentForFiles() {
	if len(g.files) == 0 {
		g.mainContent = []string{"No changes"}
		return
	}

	idx := g.fileIdx
	if idx >= len(g.files) {
		idx = len(g.files) - 1
	}
	if idx < 0 {
		return
	}

	file := g.files[idx]

	// Get diff
	var content string
	var err error

	if file.X == '?' && file.Y == '?' {
		// Untracked file
		content, err = g.repo.GetUntrackedFileDiff(file.Name)
		if err != nil {
			content = fmt.Sprintf("Error reading file: %v", err)
		}
	} else {
		// Check if staged or unstaged
		if file.Y != ' ' && file.Y != '.' {
			content, err = g.repo.GetFileDiff(file.Name, false)
		} else {
			content, err = g.repo.GetFileDiff(file.Name, true)
		}
		if err != nil || content == "" {
			// Try the other way
			if file.X != ' ' && file.X != '.' {
				content, err = g.repo.GetFileDiff(file.Name, true)
			}
		}
		if err != nil {
			content = fmt.Sprintf("Error: %v", err)
		}
	}

	lines := strings.Split(content, "\n")
	g.mainContent = lines
}

func (g *GUI) updateMainContentForBranches() {
	if len(g.branches) == 0 {
		return
	}
	idx := g.branchIdx
	if idx >= len(g.branches) {
		idx = len(g.branches) - 1
	}
	if idx < 0 {
		return
	}
	b := g.branches[idx]
	content, err := g.repo.GetBranchLog(b.Name)
	if err != nil {
		g.mainContent = []string{fmt.Sprintf("Error: %v", err)}
		return
	}
	g.mainContent = strings.Split(content, "\n")
}

func (g *GUI) updateMainContentForCommits() {
	if len(g.commits) == 0 {
		return
	}
	idx := g.commitIdx
	if idx >= len(g.commits) {
		idx = len(g.commits) - 1
	}
	if idx < 0 {
		return
	}
	c := g.commits[idx]
	content, err := g.repo.GetCommitDiff(c.Hash)
	if err != nil {
		g.mainContent = []string{fmt.Sprintf("Error: %v", err)}
		return
	}
	g.mainContent = strings.Split(content, "\n")
}

func (g *GUI) render() {
	g.screen.Clear()

	// Calculate layout
	sideWidth := g.width / 3
	if sideWidth < 20 {
		sideWidth = 20
	}
	mainWidth := g.width - sideWidth

	// Heights for left panel sections
	// Status: 3 rows
	// Files: dynamic
	// Branches: dynamic
	// Commits: dynamic
	// Stash: 4 rows
	// CommandLog: 7 rows (in main area)

	statusH := 3
	stashH := 4
	commandLogH := 7

	remaining := g.height - 1 - statusH - stashH // 1 for bottom bar
	if remaining < 10 {
		remaining = 10
	}

	// Distribute remaining: files, branches, commits each get 1/3
	filesH := remaining / 3
	if filesH < 3 {
		filesH = 3
	}
	branchesH := remaining / 3
	if branchesH < 3 {
		branchesH = 3
	}
	commitsH := remaining - filesH - branchesH
	if commitsH < 3 {
		commitsH = 3
	}

	mainH := g.height - 1 - commandLogH
	if mainH < 5 {
		mainH = 5
	}

	// Y positions
	statusY := 0
	filesY := statusY + statusH
	branchesY := filesY + filesH
	commitsY := branchesY + branchesH
	stashY := commitsY + commitsH
	mainY := 0
	commandLogY := mainH

	// Draw panels
	g.drawStatus(0, statusY, sideWidth, statusH)
	g.drawFiles(0, filesY, sideWidth, filesH)
	g.drawBranches(0, branchesY, sideWidth, branchesH)
	g.drawCommits(0, commitsY, sideWidth, commitsH)
	g.drawStash(0, stashY, sideWidth, stashH)
	g.drawMain(sideWidth, mainY, mainWidth, mainH)
	g.drawCommandLog(sideWidth, commandLogY, mainWidth, commandLogH)

	// Bottom bar
	g.drawBottomBar(0, g.height-1, g.width)

	// Draw popups on top
	if g.showWelcome && !g.popupDismissed {
		g.drawWelcomePopup()
	}

	if g.showInput {
		g.drawInputPrompt()
	}

	if g.showConfirm {
		g.drawConfirmDialog()
	}

	// Flush to stdout
	out := g.screen.Render()
	fmt.Fprint(os.Stdout, out)
}

func (g *GUI) borderStyle(panelID int) string {
	if g.focusedPanel == panelID {
		return Bold + FgGreen
	}
	return FgDefault
}

func (g *GUI) drawStatus(x, y, w, h int) {
	style := g.borderStyle(PanelStatus)

	title := []TitlePart{
		{Text: "─", Style: style},
		{Text: "[1]", Style: style + Bold},
		{Text: "─Status", Style: style},
		{Text: strings.Repeat("─", w-10), Style: style},
	}
	g.screen.DrawBorderWithTitle(x, y, w, h, style, title, "")

	// Content: repo → branch
	branch, _ := g.repo.GetCurrentBranch()
	repoName := g.repo.RepoName()
	content := repoName + " → " + branch

	g.screen.WriteString(x+1, y+1, TruncateString(content, w-2), FgDefault)
}

func (g *GUI) drawFiles(x, y, w, h int) {
	style := g.borderStyle(PanelFiles)

	// Tab titles
	tabs := []string{"Files", "Worktrees", "Submodules"}
	titleStr := "─[2]─" + buildTabTitle(tabs, g.filesTab) + "─"

	title := []TitlePart{
		{Text: titleStr, Style: style},
	}

	// Footer: N of M
	total := len(g.files)
	if total == 0 {
		total = 1 // avoid division by zero display
	}
	cur := g.fileIdx + 1
	if g.focusedPanel == PanelFiles && len(g.files) == 0 {
		cur = 0
		total = 0
	}
	footer := fmt.Sprintf("%d of %d", cur, len(g.files))
	if len(g.files) == 0 {
		footer = ""
	}

	g.screen.DrawBorderWithTitle(x, y, w, h, style, title, footer)

	// Content
	innerW := w - 2
	innerH := h - 2

	// Show file tree header
	if innerH > 0 {
		treeHeader := "▼ /"
		g.screen.WriteString(x+1, y+1, TruncateString(treeHeader, innerW), FgDefault)
	}

	// Files list
	for i, f := range g.files {
		row := i + 1 + 1 // +1 for border, +1 for tree header
		if row >= y+h-1 {
			break
		}

		lineStyle := FgDefault
		if g.focusedPanel == PanelFiles && i == g.fileIdx {
			lineStyle = BgBlue + FgWhite
		} else if g.focusedPanel != PanelFiles && i == g.fileIdx {
			lineStyle = Bold
		}

		// Format: "   M filename" or "  ?? filename"
		var statusStr string
		if f.X == '?' && f.Y == '?' {
			statusStr = " ?? "
		} else {
			statusStr = fmt.Sprintf("  %c%c ", f.X, f.Y)
		}

		line := statusStr + f.Name

		// Apply color based on status
		fileStyle := lineStyle
		if f.Y != ' ' && f.Y != '.' && f.Y != '?' {
			if lineStyle == FgDefault {
				fileStyle = FgRed
			}
		}
		if f.X == '?' && f.Y == '?' {
			if lineStyle == FgDefault {
				fileStyle = FgRed
			}
		}

		g.screen.FillLine(x+1, row, innerW, lineStyle)
		g.screen.WriteString(x+1, row, TruncateString(line, innerW), fileStyle)
	}
}

