func (g *GUI) handleMainKey(evt terminal.Event) {
	switch evt.Key {
	case terminal.KeyUp:
		if g.mainOffset > 0 {
			g.mainOffset--
			g.dirty = true
		}
	case terminal.KeyDown:
		g.mainOffset++
		maxOff := len(g.mainContent) - 5
		if maxOff < 0 {
			maxOff = 0
		}
		if g.mainOffset > maxOff {
			g.mainOffset = maxOff
		}
		g.dirty = true
	}

	switch evt.Rune {
	case 'K':
		if g.mainOffset > 0 {
			g.mainOffset -= 2
			if g.mainOffset < 0 {
				g.mainOffset = 0
			}
			g.dirty = true
		}
	case 'J':
		g.mainOffset += 2
		maxOff := len(g.mainContent) - 5
		if maxOff < 0 {
			maxOff = 0
		}
		if g.mainOffset > maxOff {
			g.mainOffset = maxOff
		}
		g.dirty = true
	case 'h':
		// Scroll left (placeholder)
	case 'l':
		// Scroll right (placeholder)
	}
}

func (g *GUI) handleSearchKey(evt terminal.Event) {
	switch evt.Key {
	case terminal.KeyEsc:
		g.searching = false
		g.searchQuery = ""
		g.dirty = true
	case terminal.KeyEnter:
		g.searching = false
		g.dirty = true
	case terminal.KeyBackspace:
		if len(g.searchQuery) > 0 {
			g.searchQuery = g.searchQuery[:len(g.searchQuery)-1]
			g.dirty = true
		}
	default:
		if evt.Rune != 0 && evt.Rune >= ' ' {
			g.searchQuery += string(evt.Rune)
			g.dirty = true
		}
	}
}

func (g *GUI) handleInputKey(evt terminal.Event) {
	switch evt.Key {
	case terminal.KeyEsc:
		g.showInput = false
		g.dirty = true
	case terminal.KeyEnter:
		g.showInput = false
		if g.inputCallback != nil {
			g.inputCallback(g.inputValue)
		}
		g.dirty = true
	case terminal.KeyBackspace:
		if len(g.inputValue) > 0 {
			// Remove last rune
			runes := []rune(g.inputValue)
			g.inputValue = string(runes[:len(runes)-1])
			g.dirty = true
		}
	default:
		if evt.Rune != 0 && evt.Rune >= ' ' {
			g.inputValue += string(evt.Rune)
			g.dirty = true
		}
	}
}

func (g *GUI) handleConfirmKey(evt terminal.Event) {
	switch evt.Rune {
	case 'y', 'Y':
		g.showConfirm = false
		if g.confirmYes != nil {
			g.confirmYes()
		}
		g.dirty = true
	case 'n', 'N':
		g.showConfirm = false
		if g.confirmNo != nil {
			g.confirmNo()
		}
		g.dirty = true
	}

	switch evt.Key {
	case terminal.KeyEsc:
		g.showConfirm = false
		if g.confirmNo != nil {
			g.confirmNo()
		}
		g.dirty = true
	case terminal.KeyEnter:
		g.showConfirm = false
		if g.confirmYes != nil {
			g.confirmYes()
		}
		g.dirty = true
	}
}

