		{Text: "[1]", Style: style + Bold},
		{Text: "─Status", Style: style},
		{Text: strings.Repeat("─", w-10), Style: style},
	}
	g.screen.DrawBorderWithTitle(x, y, w, h, style, title, "")

	// Content: repo → branch
	branch, _ := g.repo.GetCurrentBranch()
	repoName := g.repo.RepoName()
	content := repoName + " → " + branch

	g.screen.WriteString(x+1, y+1, TruncateString(content, w-2), FgDefault)
}

func (g *GUI) drawFiles(x, y, w, h int) {
	style := g.borderStyle(PanelFiles)

	// Tab titles
	tabs := []string{"Files", "Worktrees", "Submodules"}
	titleStr := "─[2]─" + buildTabTitle(tabs, g.filesTab) + "─"

	title := []TitlePart{
		{Text: titleStr, Style: style},
	}

	// Footer: N of M
	total := len(g.files)
	if total == 0 {
		total = 1 // avoid division by zero display
	}
	cur := g.fileIdx + 1
	if g.focusedPanel == PanelFiles && len(g.files) == 0 {
		cur = 0
		total = 0
	}
	footer := fmt.Sprintf("%d of %d", cur, len(g.files))
	if len(g.files) == 0 {
		footer = ""
	}

	g.screen.DrawBorderWithTitle(x, y, w, h, style, title, footer)

	// Content
	innerW := w - 2
	innerH := h - 2

	// Show file tree header
	if innerH > 0 {
		treeHeader := "▼ /"
		g.screen.WriteString(x+1, y+1, TruncateString(treeHeader, innerW), FgDefault)
	}

	// Files list
	for i, f := range g.files {
		row := i + 1 + 1 // +1 for border, +1 for tree header
		if row >= y+h-1 {
			break
		}

		lineStyle := FgDefault
		if g.focusedPanel == PanelFiles && i == g.fileIdx {
			lineStyle = BgBlue + FgWhite
		} else if g.focusedPanel != PanelFiles && i == g.fileIdx {
			lineStyle = Bold
		}

		// Format: "   M filename" or "  ?? filename"
		var statusStr string
		if f.X == '?' && f.Y == '?' {
			statusStr = " ?? "
		} else {
			statusStr = fmt.Sprintf("  %c%c ", f.X, f.Y)
		}

		line := statusStr + f.Name

		// Apply color based on status
		fileStyle := lineStyle
		if f.Y != ' ' && f.Y != '.' && f.Y != '?' {
			if lineStyle == FgDefault {
				fileStyle = FgRed
			}
		}
		if f.X == '?' && f.Y == '?' {
			if lineStyle == FgDefault {
				fileStyle = FgRed
			}
		}

		g.screen.FillLine(x+1, row, innerW, lineStyle)
		g.screen.WriteString(x+1, row, TruncateString(line, innerW), fileStyle)
	}
}

