func (g *GUI) drawMain(x, y, w, h int) {
	style := g.borderStyle(PanelMain)

	// Title depends on context
	var titleStr string
	switch g.focusedPanel {
	case PanelFiles:
		// Check if staged or unstaged
		if g.fileIdx < len(g.files) {
			f := g.files[g.fileIdx]
			if f.X != ' ' && f.X != '.' {
				titleStr = "─[0]─Staged changes"
			} else {
				titleStr = "─[0]─Unstaged changes"
			}
		} else {
			titleStr = "─[0]─Unstaged changes"
		}
	case PanelCommits:
		titleStr = "─[0]─Patch"
	case PanelBranches:
		titleStr = "─[0]─Log"
	default:
		titleStr = "─[0]─"
	}

	title := []TitlePart{
		{Text: titleStr, Style: style},
	}

	g.screen.DrawBorderWithTitle(x, y, w, h, style, title, "")

	// Draw content
	innerW := w - 2
	innerH := h - 2

	// Right side indicator
	for i := 1; i < h-1; i++ {
		g.screen.SetCell(x+w-1, y+i, '▐', style)
	}

	for i := 0; i < innerH; i++ {
		lineIdx := g.mainOffset + i
		if lineIdx >= len(g.mainContent) {
			break
		}
		line := g.mainContent[lineIdx]
		// Strip ANSI codes for our renderer (we'll re-apply colors)
		line = stripANSI(line)
		coloredLine := ColorizeGitDiff(line)
		// Write colored line to screen
		col := x + 1
		row := y + 1 + i

		// Parse the colored line and write each segment
		writeColoredLine(g.screen, col, row, coloredLine, innerW)
	}
}

