// buildTabTitle builds a tab title string like "Files - Worktrees - Submodules"
func buildTabTitle(tabs []string, active int) string {
	parts := make([]string, len(tabs))
	for i, tab := range tabs {
		parts[i] = tab
	}
	return strings.Join(parts, " - ")
}

// stripANSI removes ANSI escape codes from a string
func stripANSI(s string) string {
	var result strings.Builder
	i := 0
	for i < len(s) {
		if s[i] == 0x1b && i+1 < len(s) && s[i+1] == '[' {
			// Find end of sequence
			i += 2
			for i < len(s) && s[i] != 'm' && s[i] != 'J' && s[i] != 'H' && s[i] != 'K' {
				i++
			}
			i++ // skip the terminator
		} else {
			result.WriteByte(s[i])
			i++
		}
	}
	return result.String()
}

// writeColoredLine writes a line with color codes parsed
func writeColoredLine(s *Screen, x, y int, line string, maxW int) {
	col := x
	currentStyle := ""
	i := 0
	text := line

	for i < len(text) && col < x+maxW {
		if text[i] == 0x1b && i+1 < len(text) && text[i+1] == '[' {
			// Parse ANSI escape sequence
			start := i
			i += 2
			for i < len(text) && text[i] != 'm' {
				i++
			}
			if i < len(text) {
				i++
			}
			currentStyle = text[start:i]
		} else {
			r, size := decodeRune(text[i:])
			if r == '\t' {
				// Tab -> spaces
				s.SetCell(col, y, ' ', currentStyle)
				col++
			} else if r >= ' ' || r == 0 {
				s.SetCell(col, y, r, currentStyle)
				w := runeWidth(r)
				if w > 1 && col+1 < x+maxW {
					s.SetCell(col+1, y, ' ', currentStyle)
				}
				col += w
			}
			i += size
		}
	}
}

func decodeRune(s string) (rune, int) {
	if len(s) == 0 {
		return 0, 0
	}
	b := s[0]
	if b < 0x80 {
		return rune(b), 1
	}
	if b < 0xC0 {
		return rune(b), 1
	}
	if b < 0xE0 && len(s) >= 2 {
		return rune(b&0x1F)<<6 | rune(s[1]&0x3F), 2
	}
	if b < 0xF0 && len(s) >= 3 {
		return rune(b&0x0F)<<12 | rune(s[1]&0x3F)<<6 | rune(s[2]&0x3F), 3
	}
	if len(s) >= 4 {
		return rune(b&0x07)<<18 | rune(s[1]&0x3F)<<12 | rune(s[2]&0x3F)<<6 | rune(s[3]&0x3F), 4
	}
	return rune(b), 1
}

// GetLogFile returns the log file path
func GetLogFile() string {
	home, _ := os.UserHomeDir()
	xdgState := os.Getenv("XDG_STATE_HOME")
	if xdgState == "" {
		xdgState = filepath.Join(home, ".local", "state")
	}
	return filepath.Join(xdgState, "lazygit", "development.log")
}
