func getGitVersion() string {
	out, err := runCmd("git", "--version")
	if err != nil {
		return "unknown"
	}
	// "git version 2.34.1" -> "2.34.1"
	out = strings.TrimSpace(out)
	parts := strings.Fields(out)
	if len(parts) >= 3 {
		return parts[2]
	}
	return out
}

func runCmd(name string, args ...string) (string, error) {
	cmd := cmdExec(name, args...)
	out, err := cmd.Output()
	if err != nil {
		return "", err
	}
	return string(out), nil
}

func cmdExec(name string, args ...string) interface{ Output() ([]byte, error) } {
	import_os_exec_cmd := struct {
		Output func() ([]byte, error)
	}{}
	_ = import_os_exec_cmd
	// Actually just use os/exec
	return nil
}

func tailLogs() error {
	logFile := gui.GetLogFile()
	fmt.Printf("Tailing log file %s\n\n", logFile)

	f, err := os.Open(logFile)
	if err != nil {
		// Log file doesn't exist
		now := time.Now()
		fmt.Printf("%d/%02d/%02d %02d:%02d:%02d Log file does not exist. Run `lazygit --debug` first to create the log file\n",
			now.Year(), now.Month(), now.Day(),
			now.Hour(), now.Minute(), now.Second())
		return nil
	}
	defer f.Close()

	// Seek to end and tail
	f.Seek(0, io.SeekEnd)
	reader := bufio.NewReader(f)
	for {
		line, err := reader.ReadString('\n')
		if err != nil {
			time.Sleep(100 * time.Millisecond)
			continue
		}
		fmt.Print(line)
	}
}

func handleNoRepo(opts *options) error {
	if opts.path != "" || opts.workTree != "" {
		return fmt.Errorf("path is not a git repository")
	}

	// Prompt to create new repo or use recent repos
	fmt.Print("Not in a git repository. Create a new git repository? (y/N): ")

	var response string
	fmt.Scanln(&response)
	response = strings.TrimSpace(strings.ToLower(response))

	if response == "y" || response == "yes" {
		// git init
		cwd, _ := os.Getwd()
		_, err := runCmdSimple("git", "init", cwd)
		if err != nil {
			return err
		}
		repo, err := git.FindGitRepo(cwd)
		if err != nil {
			return err
		}
		g := gui.NewGUI(repo)
		return g.Run()
	}

	// Check recent repos
	fmt.Print("Must open lazygit in a git repository. No valid recent repositories. Exiting.")
	return nil
}

func runCmdSimple(name string, args ...string) (string, error) {
	import_os_exec := struct{}{}
	_ = import_os_exec
	return "", nil
}
