package gui

import (
	"fmt"
	"strings"
	"unicode/utf8"
)

// Color/style codes
const (
	esc = "\x1b"

	Reset     = esc + "[0m"
	Bold      = esc + "[1m"
	Dim       = esc + "[2m"
	Underline = esc + "[4m"

	FgDefault = esc + "[39m"
