	BgGreen   = esc + "[42m"
	BgYellow  = esc + "[43m"
	BgBlue    = esc + "[44m"
	BgMagenta = esc + "[45m"
	BgCyan    = esc + "[46m"
	BgWhite   = esc + "[47m"
)

// Screen represents the terminal screen buffer
type Screen struct {
	Width  int
	Height int
	buf    [][]Cell
}

type Cell struct {
	Ch    rune
	Style string
}

func NewScreen(w, h int) *Screen {
	s := &Screen{Width: w, Height: h}
	s.buf = make([][]Cell, h)
	for i := range s.buf {
		s.buf[i] = make([]Cell, w)
		for j := range s.buf[i] {
			s.buf[i][j] = Cell{Ch: ' ', Style: ""}
		}
	}
	return s
}

func (s *Screen) SetCell(x, y int, ch rune, style string) {
	if y < 0 || y >= s.Height || x < 0 || x >= s.Width {
		return
	}
	s.buf[y][x] = Cell{Ch: ch, Style: style}
}

// WriteString writes a string at position, returns number of columns used
func (s *Screen) WriteString(x, y int, str string, style string) int {
	col := x
	for _, r := range str {
		if col >= s.Width {
			break
		}
		s.SetCell(col, y, r, style)
		w := RuneWidth(r)
		if w > 1 {
			if col+1 < s.Width {
				s.SetCell(col+1, y, ' ', style)
			}
			col += w
		} else {
			col++
		}
	}
	return col - x
}

// WriteRunes writes runes with per-rune styles
func (s *Screen) WriteStyledRunes(x, y int, runes []StyledRune) int {
	col := x
	for _, sr := range runes {
		if col >= s.Width {
			break
		}
		s.SetCell(col, y, sr.Ch, sr.Style)
		w := RuneWidth(sr.Ch)
		if w > 1 {
			if col+1 < s.Width {
				s.SetCell(col+1, y, ' ', sr.Style)
			}
			col += w
		} else {
			col++
		}
	}
	return col - x
}

type StyledRune struct {
	Ch    rune
	Style string
}

func (s *Screen) FillLine(x, y, width int, style string) {
	for i := x; i < x+width && i < s.Width; i++ {
		s.SetCell(i, y, ' ', style)
	}
}

func (s *Screen) Render() string {
	var sb strings.Builder
	sb.WriteString(esc + "[H")
	sb.WriteString(esc + "[?25l")

	currentStyle := ""
	for y := 0; y < s.Height; y++ {
		for x := 0; x < s.Width; x++ {
			cell := s.buf[y][x]
			if cell.Style != currentStyle {
				if currentStyle != "" {
					sb.WriteString(Reset)
				}
				if cell.Style != "" {
					sb.WriteString(cell.Style)
				}
				currentStyle = cell.Style
			}
			if cell.Ch == 0 {
				sb.WriteRune(' ')
			} else {
				sb.WriteRune(cell.Ch)
			}
		}
		if y < s.Height-1 {
			if currentStyle != "" {
				sb.WriteString(Reset)
				currentStyle = ""
			}
			sb.WriteString("\r\n")
		}
	}
	if currentStyle != "" {
		sb.WriteString(Reset)
	}
	return sb.String()
}

func (s *Screen) Clear() {
	for y := range s.buf {
		for x := range s.buf[y] {
			s.buf[y][x] = Cell{Ch: ' ', Style: ""}
		}
	}
}

// RuneWidth returns the display width of a rune
func RuneWidth(r rune) int {
	if r == 0 || r == '\t' {
		return 1
	}
	if r < 32 || r == 127 {
		return 0
	}
	if isWideRune(r) {
		return 2
	}
	return 1
}

func isWideRune(r rune) bool {
	if r >= 0x1100 && r <= 0x115F {
		return true
	}
	if r == 0x2329 || r == 0x232A {
		return true
	}
	if r >= 0x2E80 && r <= 0x303E {
		return true
	}
	if r >= 0x3040 && r <= 0x33FF {
		return true
	}
	if r >= 0x3400 && r <= 0x4DBF {
		return true
	}
	if r >= 0x4E00 && r <= 0x9FFF {
		return true
	}
	if r >= 0xA000 && r <= 0xA4CF {
		return true
	}
	if r >= 0xAC00 && r <= 0xD7FF {
		return true
	}
	if r >= 0xF900 && r <= 0xFAFF {
		return true
	}
	if r >= 0xFF00 && r <= 0xFF60 {
		return true
	}
	if r >= 0xFFE0 && r <= 0xFFE6 {
		return true
	}
	return false
}

// StringWidth returns display width of a string
func StringWidth(s string) int {
	w := 0
	for _, r := range s {
		w += RuneWidth(r)
	}
	return w
}

// TruncateString truncates string to fit in maxWidth display columns
func TruncateString(s string, maxWidth int) string {
	if maxWidth <= 0 {
		return ""
	}
	w := 0
	result := make([]rune, 0, len(s))
	for _, r := range s {
		rw := RuneWidth(r)
		if w+rw > maxWidth {
			break
		}
		w += rw
		result = append(result, r)
	}
	return string(result)
}

// PadRight pads string to exactly width display columns
func PadRight(s string, width int) string {
	sw := StringWidth(s)
	if sw >= width {
		return TruncateString(s, width)
	}
	return s + strings.Repeat(" ", width-sw)
}

// DrawBox draws a box with rounded corners
// title: appears after the first ─ on top border
// footer: appears before the right corner on bottom border
func (s *Screen) DrawBox(x, y, w, h int, borderStyle string, title string, footer string) {
	if w < 2 || h < 2 {
		return
	}

	// Top border
	s.SetCell(x, y, '╭', borderStyle)

	// Build top line content: ─title─────────
	innerW := w - 2
	titleRunes := []rune("─" + title)
	col := x + 1
	for i, r := range titleRunes {
		if col >= x+w-1 {
			break
		}
		_ = i
		s.SetCell(col, y, r, borderStyle)
		col++
	}
	// Fill remaining with ─
	for col < x+w-1 {
		s.SetCell(col, y, '─', borderStyle)
		col++
	}
	s.SetCell(x+w-1, y, '╮', borderStyle)

	// Side borders
	for i := 1; i < h-1; i++ {
		s.SetCell(x, y+i, '│', borderStyle)
		s.SetCell(x+w-1, y+i, '│', borderStyle)
	}

	// Bottom border
	s.SetCell(x, y+h-1, '╰', borderStyle)
	if footer != "" {
		footerStr := "─" + footer + "─"
		fw := utf8.RuneCountInString(footerStr)
		startX := x + w - 1 - fw
		if startX < x+1 {
			startX = x + 1
		}
		for i := x + 1; i < startX; i++ {
			s.SetCell(i, y+h-1, '─', borderStyle)
		}
		col := startX
		for _, r := range footerStr {
			if col >= x+w-1 {
				break
			}
			s.SetCell(col, y+h-1, r, borderStyle)
			col++
		}
		for col < x+w-1 {
			s.SetCell(col, y+h-1, '─', borderStyle)
			col++
		}
