// ColorizeGitDiff applies colors to git diff output line
func ColorizeGitDiff(line string) string {
	if len(line) == 0 {
		return ""
	}
	switch {
	case strings.HasPrefix(line, "+++"):
		return FgGreen + line + Reset
	case strings.HasPrefix(line, "---"):
		return FgRed + line + Reset
	case strings.HasPrefix(line, "+"):
		return FgGreen + line + Reset
	case strings.HasPrefix(line, "-"):
		return FgRed + line + Reset
	case strings.HasPrefix(line, "@@"):
		return FgCyan + line + Reset
	case strings.HasPrefix(line, "diff"):
		return Bold + line + Reset
	case strings.HasPrefix(line, "index"):
		return Dim + line + Reset
	default:
		return line
	}
}

// stripANSI removes ANSI escape codes from a string
func stripANSI(s string) string {
	var result strings.Builder
	i := 0
	for i < len(s) {
		if s[i] == 0x1b && i+1 < len(s) && s[i+1] == '[' {
			i += 2
			for i < len(s) && s[i] != 'm' && s[i] != 'J' && s[i] != 'H' && s[i] != 'K' {
				i++
			}
			i++
		} else {
			result.WriteByte(s[i])
			i++
		}
	}
	return result.String()
}

// writeColoredLine parses ANSI codes inline and writes colored content to screen
func writeColoredLine(scr *Screen, x, y int, line string, maxW int) {
	col := x
	currentStyle := ""
	i := 0

	for i < len(line) && col < x+maxW {
		if line[i] == 0x1b && i+1 < len(line) && line[i+1] == '[' {
			// Parse ANSI escape sequence
			start := i
			i += 2
			for i < len(line) && line[i] != 'm' {
				i++
			}
			if i < len(line) {
				i++ // skip 'm'
			}
			seq := line[start:i]
			if seq == Reset || seq == esc+"[0m" {
				currentStyle = ""
			} else {
				currentStyle = seq
			}
		} else {
			r, size := decodeRuneBytes(line[i:])
			if r == '\t' {
				scr.SetCell(col, y, ' ', currentStyle)
				col++
			} else if r >= ' ' {
				scr.SetCell(col, y, r, currentStyle)
				rw := RuneWidth(r)
				if rw > 1 && col+1 < x+maxW {
					scr.SetCell(col+1, y, ' ', currentStyle)
				}
				col += rw
			}
			i += size
		}
	}
}

func decodeRuneBytes(s string) (rune, int) {
	if len(s) == 0 {
		return 0, 0
	}
	r, size := utf8.DecodeRuneInString(s)
	if r == utf8.RuneError && size == 1 {
		return rune(s[0]), 1
	}
	return r, size
}

// Sprintf for footer: "N of M─"
func FooterText(cur, total int) string {
	return fmt.Sprintf("%d of %d", cur, total)
}
