func (g *GUI) drawMain(x, y, w, h int) {
	style := g.borderStyle(PanelMain)

	var titleStr string
	switch g.focusedPanel {
	case PanelFiles:
		if g.fileIdx < len(g.files) {
			f := g.files[g.fileIdx]
			if f.X != ' ' && f.X != '.' && f.X != '?' {
				titleStr = "─[0]─Staged changes"
			} else {
				titleStr = "─[0]─Unstaged changes"
			}
		} else {
			titleStr = "─[0]─Unstaged changes"
		}
	case PanelCommits:
		titleStr = "─[0]─Patch"
	case PanelBranches:
		titleStr = "─[0]─Log"
	default:
		titleStr = "─[0]─"
	}

	title := makeTitle(style, titleStr)
	g.screen.DrawBoxWithStyledTitle(x, y, w, h, style, title, "")

	// Right edge indicator: ▐ instead of │
	for i := 1; i < h-1; i++ {
		g.screen.SetCell(x+w-1, y+i, '▐', style)
	}

	innerW := w - 2
	innerH := h - 2

	for i := 0; i < innerH; i++ {
		lineIdx := g.mainOffset + i
		if lineIdx >= len(g.mainContent) {
			break
		}
		line := stripANSI(g.mainContent[lineIdx])
		coloredLine := ColorizeGitDiff(line)
		writeColoredLine(g.screen, x+1, y+1+i, coloredLine, innerW)
	}
}

