func (g *GUI) Run() error {
	if err := terminal.EnableRawMode(); err != nil {
		return err
	}
	defer terminal.DisableRawMode()

	w, h, err := terminal.GetSize()
	if err != nil || w == 0 {
		w, h = 80, 24
	}
	g.width = w
	g.height = h
	g.screen = NewScreen(w, h)

	fmt.Fprint(os.Stdout, terminal.AltScreen())
	fmt.Fprint(os.Stdout, terminal.HideCursor())
	fmt.Fprint(os.Stdout, terminal.EnableMouse())

	defer func() {
		fmt.Fprint(os.Stdout, terminal.DisableMouse())
		fmt.Fprint(os.Stdout, terminal.ShowCursor())
		fmt.Fprint(os.Stdout, terminal.MainScreen())
	}()

	if err := g.refresh(); err != nil {
		return err
