func (g *GUI) updateMainForFiles() {
	if len(g.files) == 0 {
		g.mainContent = []string{}
		return
	}
	idx := g.fileIdx
	if idx >= len(g.files) {
		idx = len(g.files) - 1
	}
	if idx < 0 {
		return
	}
	file := g.files[idx]
	var content string
	var err error
	if file.X == '?' && file.Y == '?' {
		content, err = g.repo.GetUntrackedFileDiff(file.Name)
		if err != nil {
			content = fmt.Sprintf("Error: %v", err)
		}
	} else {
		if file.Y != ' ' && file.Y != '.' {
			content, _ = g.repo.GetFileDiff(file.Name, false)
		}
		if content == "" && file.X != ' ' && file.X != '.' {
			content, err = g.repo.GetFileDiff(file.Name, true)
			if err != nil {
				content = fmt.Sprintf("Error: %v", err)
			}
		}
	}
	g.mainContent = strings.Split(content, "\n")
}

func (g *GUI) updateMainForBranches() {
	if len(g.branches) == 0 {
