	}
	g.commits, err = g.repo.GetCommits(100)
	if err != nil {
		g.commits = nil
	}
	g.stash, err = g.repo.GetStash()
	if err != nil {
		g.stash = nil
	}
	g.updateMainContent()
	g.dirty = true
	return nil
}

func (g *GUI) addCommandLog(msg string) {
