	maxEntries := 20
	if len(g.commandLog) > maxEntries {
		g.commandLog = g.commandLog[len(g.commandLog)-maxEntries:]
	}
}

func (g *GUI) updateMainContent() {
	g.mainContent = nil
	g.mainOffset = 0

	switch g.focusedPanel {
	case PanelFiles:
		g.updateMainForFiles()
	case PanelBranches:
		g.updateMainForBranches()
	case PanelCommits:
		g.updateMainForCommits()
	}
}

func (g *GUI) updateMainForFiles() {
	if len(g.files) == 0 {
		g.mainContent = []string{}
		return
	}
	idx := g.fileIdx
	if idx >= len(g.files) {
		idx = len(g.files) - 1
	}
	if idx < 0 {
		return
	}
	file := g.files[idx]
	var content string
	var err error
	if file.X == '?' && file.Y == '?' {
		content, err = g.repo.GetUntrackedFileDiff(file.Name)
		if err != nil {
			content = fmt.Sprintf("Error: %v", err)
		}
	} else {
		if file.Y != ' ' && file.Y != '.' {
			content, _ = g.repo.GetFileDiff(file.Name, false)
		}
		if content == "" && file.X != ' ' && file.X != '.' {
			content, err = g.repo.GetFileDiff(file.Name, true)
			if err != nil {
				content = fmt.Sprintf("Error: %v", err)
			}
		}
	}
	g.mainContent = strings.Split(content, "\n")
}

func (g *GUI) updateMainForBranches() {
	if len(g.branches) == 0 {
		return
	}
	idx := g.branchIdx
	if idx >= len(g.branches) {
		idx = len(g.branches) - 1
	}
	if idx < 0 {
		return
	}
	b := g.branches[idx]
	content, err := g.repo.GetBranchLog(b.Name)
	if err != nil {
		g.mainContent = []string{fmt.Sprintf("Error: %v", err)}
		return
	}
	g.mainContent = strings.Split(content, "\n")
}

func (g *GUI) updateMainForCommits() {
	if len(g.commits) == 0 {
		return
	}
	idx := g.commitIdx
	if idx >= len(g.commits) {
		idx = len(g.commits) - 1
	}
	if idx < 0 {
		return
	}
	c := g.commits[idx]
	content, err := g.repo.GetCommitDiff(c.Hash)
	if err != nil {
		g.mainContent = []string{fmt.Sprintf("Error: %v", err)}
		return
	}
	g.mainContent = strings.Split(content, "\n")
}

// Layout calculation
type layout struct {
	sideW int
	mainW int

	statusY   int
	statusH   int
	filesY    int
	filesH    int
	branchesY int
	branchesH int
	commitsY  int
	commitsH  int
	stashY    int
	stashH    int

	mainY      int
	mainH      int
	cmdLogY    int
	cmdLogH    int
	bottomBarY int
}

func (g *GUI) calcLayout() layout {
	var l layout
	l.sideW = g.width / 3
	if l.sideW < 20 {
		l.sideW = 20
	}
	if l.sideW > g.width-20 {
		l.sideW = g.width - 20
	}
	l.mainW = g.width - l.sideW

	l.statusH = 3
	l.stashH = 4
	l.cmdLogH = 7

	usedH := l.statusH + l.stashH + 1 // +1 for bottom bar
	remaining := g.height - usedH
	if remaining < 9 {
		remaining = 9
	}

	l.filesH = remaining / 3
	if l.filesH < 3 {
		l.filesH = 3
	}
	l.branchesH = remaining / 3
	if l.branchesH < 3 {
		l.branchesH = 3
	}
	l.commitsH = remaining - l.filesH - l.branchesH
	if l.commitsH < 3 {
		l.commitsH = 3
	}

	l.statusY = 0
	l.filesY = l.statusY + l.statusH
	l.branchesY = l.filesY + l.filesH
	l.commitsY = l.branchesY + l.branchesH
	l.stashY = l.commitsY + l.commitsH

	l.mainH = g.height - 1 - l.cmdLogH
	if l.mainH < 3 {
		l.mainH = 3
	}
	l.mainY = 0
	l.cmdLogY = l.mainH
	l.bottomBarY = g.height - 1

	return l
}

func (g *GUI) render() {
	g.screen.Clear()
	l := g.calcLayout()

	g.drawStatus(0, l.statusY, l.sideW, l.statusH)
	g.drawFiles(0, l.filesY, l.sideW, l.filesH)
	g.drawBranches(0, l.branchesY, l.sideW, l.branchesH)
	g.drawCommits(0, l.commitsY, l.sideW, l.commitsH)
	g.drawStash(0, l.stashY, l.sideW, l.stashH)
	g.drawMain(l.sideW, l.mainY, l.mainW, l.mainH)
	g.drawCommandLog(l.sideW, l.cmdLogY, l.mainW, l.cmdLogH)
	g.drawBottomBar(0, l.bottomBarY, g.width)

	// Overlays
	if g.showWelcome && !g.popupDismissed {
		g.drawWelcomePopup()
	}
	if g.showInput {
		g.drawInputPrompt()
	}
	if g.showConfirm {
		g.drawConfirmDialog()
	}

	fmt.Fprint(os.Stdout, g.screen.Render())
}

func (g *GUI) activeBorderStyle() string {
	return Bold + FgGreen
}

func (g *GUI) inactiveBorderStyle() string {
	return "" // default
}

func (g *GUI) borderStyle(panelID int) string {
	if g.focusedPanel == panelID {
		return g.activeBorderStyle()
	}
	return g.inactiveBorderStyle()
}

func makeTitle(borderStyle string, parts ...string) []StyledRune {
	var runes []StyledRune
	for _, p := range parts {
		for _, r := range p {
			runes = append(runes, StyledRune{Ch: r, Style: borderStyle})
		}
	}
	return runes
}

func (g *GUI) drawStatus(x, y, w, h int) {
	style := g.borderStyle(PanelStatus)
	title := makeTitle(style, "─[1]─Status")
	g.screen.DrawBoxWithStyledTitle(x, y, w, h, style, title, "")

	branch, _ := g.repo.GetCurrentBranch()
	repoName := g.repo.RepoName()
	content := repoName + " → " + branch

	g.screen.WriteString(x+1, y+1, TruncateString(content, w-2), "")
}

func (g *GUI) drawFiles(x, y, w, h int) {
	style := g.borderStyle(PanelFiles)
	titleStr := "─[2]─Files - Worktrees - Submodules"
	title := makeTitle(style, titleStr)
	g.screen.DrawBoxWithStyledTitle(x, y, w, h, style, title, g.filesFooter())

	innerW := w - 2
	innerH := h - 2

	// Tree header
	if innerH > 0 {
		g.screen.WriteString(x+1, y+1, TruncateString("▼ /", innerW), "")
	}

	// Files list
	startRow := y + 2
	for i, f := range g.files {
		row := startRow + i
		if row >= y+h-1 {
			break
		}
		lineStyle := g.itemStyle(PanelFiles, i)
		g.screen.FillLine(x+1, row, innerW, lineStyle)

		statusStr := g.fileStatusStr(f)
		line := statusStr + f.Name
		g.screen.WriteString(x+1, row, TruncateString(line, innerW), lineStyle)
	}
}

func (g *GUI) filesFooter() string {
	if len(g.files) == 0 {
		return ""
	}
	return FooterText(g.fileIdx+1, len(g.files))
}

func (g *GUI) fileStatusStr(f *git.FileStatus) string {
	if f.X == '?' && f.Y == '?' {
		return " ?? "
	}
	return fmt.Sprintf("  %c%c ", f.X, f.Y)
}

func (g *GUI) drawBranches(x, y, w, h int) {
	style := g.borderStyle(PanelBranches)
	titleStr := "─[3]─Local branches - Remotes - Tags"
	title := makeTitle(style, titleStr)

	footer := ""
	if len(g.branches) > 0 {
		footer = FooterText(g.branchIdx+1, len(g.branches))
	}
	g.screen.DrawBoxWithStyledTitle(x, y, w, h, style, title, footer)

	innerW := w - 2
	for i, b := range g.branches {
		row := y + 1 + i
		if row >= y+h-1 {
			break
		}
		lineStyle := g.itemStyle(PanelBranches, i)
		g.screen.FillLine(x+1, row, innerW, lineStyle)

		prefix := "  "
		if b.Current {
			prefix = "* "
		}
		line := prefix + b.Name
		g.screen.WriteString(x+1, row, TruncateString(line, innerW), lineStyle)
	}
}

func (g *GUI) drawCommits(x, y, w, h int) {
	style := g.borderStyle(PanelCommits)
	titleStr := "─[4]─Commits - Reflog"
	title := makeTitle(style, titleStr)

	footer := ""
	if len(g.commits) > 0 {
		footer = FooterText(g.commitIdx+1, len(g.commits))
	}
	g.screen.DrawBoxWithStyledTitle(x, y, w, h, style, title, footer)

	innerW := w - 2
	for i, c := range g.commits {
		row := y + 1 + i
		if row >= y+h-1 {
			break
		}
		lineStyle := g.itemStyle(PanelCommits, i)
		g.screen.FillLine(x+1, row, innerW, lineStyle)

		line := fmt.Sprintf("%s %s ◯ %s", c.ShortHash, c.AuthorInitials, c.Subject)
		g.screen.WriteString(x+1, row, TruncateString(line, innerW), lineStyle)
	}
}

func (g *GUI) drawStash(x, y, w, h int) {
	style := g.borderStyle(PanelStash)
	title := makeTitle(style, "─[5]─Stash")

	footer := FooterText(len(g.stash), len(g.stash))
	if len(g.stash) == 0 {
		footer = "0 of 0"
	} else {
		footer = FooterText(g.stashIdx+1, len(g.stash))
	}
	g.screen.DrawBoxWithStyledTitle(x, y, w, h, style, title, footer)

	innerW := w - 2
	for i, s := range g.stash {
		row := y + 1 + i
		if row >= y+h-1 {
			break
		}
		lineStyle := g.itemStyle(PanelStash, i)
		g.screen.FillLine(x+1, row, innerW, lineStyle)
		g.screen.WriteString(x+1, row, TruncateString(s.Name, innerW), lineStyle)
	}
}

func (g *GUI) drawMain(x, y, w, h int) {
	style := g.borderStyle(PanelMain)

	var titleStr string
	switch g.focusedPanel {
	case PanelFiles:
		if g.fileIdx < len(g.files) {
			f := g.files[g.fileIdx]
			if f.X != ' ' && f.X != '.' && f.X != '?' {
				titleStr = "─[0]─Staged changes"
			} else {
				titleStr = "─[0]─Unstaged changes"
			}
		} else {
			titleStr = "─[0]─Unstaged changes"
		}
	case PanelCommits:
		titleStr = "─[0]─Patch"
	case PanelBranches:
		titleStr = "─[0]─Log"
	default:
		titleStr = "─[0]─"
	}

	title := makeTitle(style, titleStr)
	g.screen.DrawBoxWithStyledTitle(x, y, w, h, style, title, "")

	// Right edge indicator: ▐ instead of │
	for i := 1; i < h-1; i++ {
		g.screen.SetCell(x+w-1, y+i, '▐', style)
	}

	innerW := w - 2
	innerH := h - 2

	for i := 0; i < innerH; i++ {
		lineIdx := g.mainOffset + i
		if lineIdx >= len(g.mainContent) {
			break
		}
		line := stripANSI(g.mainContent[lineIdx])
		coloredLine := ColorizeGitDiff(line)
		writeColoredLine(g.screen, x+1, y+1+i, coloredLine, innerW)
	}
}

func (g *GUI) drawCommandLog(x, y, w, h int) {
	style := g.inactiveBorderStyle()
	title := makeTitle(style, "─Command log")
	g.screen.DrawBoxWithStyledTitle(x, y, w, h, style, title, "")

	innerW := w - 2
	innerH := h - 2

	logLines := g.commandLog
	start := len(logLines) - innerH
	if start < 0 {
		start = 0
	}

	for i, line := range logLines[start:] {
		row := y + 1 + i
		if row >= y+h-1 {
			break
		}
		g.screen.WriteString(x+1, row, TruncateString(line, innerW), "")
	}
}

func (g *GUI) drawBottomBar(x, y, w int) {
	g.screen.FillLine(x, y, w, "")

	var helpText string
	switch g.focusedPanel {
	case PanelFiles:
		helpText = "Stage: <space> | Commit: c | Stash: s | Discard: d | Reset: D | Keybindings: ?"
	case PanelBranches:
		helpText = "Checkout: <space> | New branch: n | Delete: d | Rebase: r | Reset: g | Upstream: u | Keybindings: ?"
	case PanelCommits:
		helpText = "Revert: t | View files: <enter> | Cherry-pick: C | Squash: s | Keybindings: ?"
	case PanelStash:
		helpText = "Pop: g | Rename: r | Drop: d | Keybindings: ?"
	case PanelStatus:
		helpText = "View recent repos: <enter> | Keybindings: ?"
	default:
		if g.showWelcome && !g.popupDismissed {
			helpText = "Confirm: <enter> | Close/Cancel: <esc> | Copy to clipboard: <c-o>"
		} else {
			helpText = "Keybindings: ?"
		}
	}
	if g.showWelcome && !g.popupDismissed {
		helpText = "Confirm: <enter> | Close/Cancel: <esc> | Copy to clipboard: <c-o>"
	}

	version := "4fb5c7fc"
	rightStr := "Donate Ask Question " + version

	helpW := w - StringWidth(rightStr) - 1
	g.screen.WriteString(x, y, TruncateString(helpText, helpW), FgBlue)

	startRight := w - StringWidth(rightStr)
	if startRight < 0 {
		startRight = 0
	}
	g.screen.WriteString(x+startRight, y, rightStr, "")
}

