func (g *GUI) drawConfirmDialog() {
	lines := strings.Split(g.confirmMsg, "\n")
	maxW := 0
	for _, l := range lines {
		w := StringWidth(l)
		if w > maxW {
			maxW = w
		}
	}
	if maxW < 20 {
		maxW = 20
	}
	if maxW > g.width-8 {
		maxW = g.width - 8
	}

	dialogW := maxW + 4
	dialogH := len(lines) + 4
	dialogX := (g.width - dialogW) / 2
	dialogY := (g.height - dialogH) / 2

	for i := 1; i < dialogH-1; i++ {
		g.screen.FillLine(dialogX+1, dialogY+i, dialogW-2, "")
	}

	borderStyle := Bold + FgCyan
	g.screen.DrawBox(dialogX, dialogY, dialogW, dialogH, borderStyle, "", "")

	for i, line := range lines {
		g.screen.WriteString(dialogX+2, dialogY+1+i, TruncateString(line, dialogW-4), "")
	}

	buttonRow := dialogY + dialogH - 2
	g.screen.WriteString(dialogX+2, buttonRow, "(y) Yes   (n) No", "")
}

func (g *GUI) itemStyle(panelID, idx int) string {
	if g.focusedPanel == panelID && idx == g.selectedIdx(panelID) {
		return BgBlue
	}
	if g.focusedPanel != panelID && idx == g.selectedIdx(panelID) {
		return Bold
	}
	return ""
}

func (g *GUI) selectedIdx(panelID int) int {
	switch panelID {
	case PanelFiles:
		return g.fileIdx
	case PanelBranches:
		return g.branchIdx
	case PanelCommits:
		return g.commitIdx
	case PanelStash:
		return g.stashIdx
	}
	return 0
}

func (g *GUI) handleEvent(evt terminal.Event) {
	if evt.Type == terminal.EventResize {
		w, h, _ := terminal.GetSize()
		if w > 0 && h > 0 {
			g.width = w
			g.height = h
			g.screen = NewScreen(w, h)
		}
		g.dirty = true
		return
	}

	if evt.Type == terminal.EventMouse {
		return
	}

	if evt.Type != terminal.EventKey {
		return
	}

	// Handle popups
	if g.showWelcome && !g.popupDismissed {
		switch evt.Key {
		case terminal.KeyEnter, terminal.KeyEsc:
			g.popupDismissed = true
			g.dirty = true
		}
		return
	}

	if g.showInput {
		g.handleInputKey(evt)
		return
	}

	if g.showConfirm {
		g.handleConfirmKey(evt)
		return
	}

	// Global keys
	if evt.Key == terminal.KeyCtrlC {
		g.running = false
		return
	}

	switch evt.Rune {
	case 'q', 'Q':
		g.running = false
		return
	case 'R':
		g.refresh()
		g.addCommandLog("git status, git branch, git log ...")
		g.dirty = true
		return
	case '@':
		g.dirty = true
		return
	case '?':
		g.dirty = true
		return
	}

	// Panel navigation
	switch evt.Key {
	case terminal.KeyTab:
		g.focusedPanel = (g.focusedPanel + 1) % 5
		g.updateMainContent()
		g.dirty = true
		return
	case terminal.KeyBackTab:
		g.focusedPanel = (g.focusedPanel + 4) % 5
		g.updateMainContent()
		g.dirty = true
		return
	}

	// Jump to panel by number
	switch evt.Rune {
	case '1':
		g.focusedPanel = PanelStatus
		g.updateMainContent()
		g.dirty = true
		return
	case '2':
		g.focusedPanel = PanelFiles
		g.updateMainContent()
		g.dirty = true
		return
	case '3':
		g.focusedPanel = PanelBranches
		g.updateMainContent()
		g.dirty = true
		return
	case '4':
		g.focusedPanel = PanelCommits
		g.updateMainContent()
		g.dirty = true
		return
	case '5':
		g.focusedPanel = PanelStash
		g.updateMainContent()
		g.dirty = true
		return
	case '0':
		g.focusedPanel = PanelMain
		g.dirty = true
		return
	}

	// Main view global scrolling
	switch evt.Key {
	case terminal.KeyPageUp:
		if g.mainOffset > 0 {
			g.mainOffset -= 10
			if g.mainOffset < 0 {
				g.mainOffset = 0
			}
			g.dirty = true
		}
		return
	case terminal.KeyPageDown:
		g.mainOffset += 10
		g.clampMainOffset()
		g.dirty = true
		return
	}

	// Panel-specific handling
	switch g.focusedPanel {
	case PanelStatus:
		g.handleStatusKeys(evt)
	case PanelFiles:
		g.handleFilesKeys(evt)
	case PanelBranches:
		g.handleBranchesKeys(evt)
	case PanelCommits:
		g.handleCommitsKeys(evt)
	case PanelStash:
		g.handleStashKeys(evt)
	case PanelMain:
		g.handleMainKeys(evt)
	}
}

func (g *GUI) clampMainOffset() {
	max := len(g.mainContent) - 5
	if max < 0 {
		max = 0
	}
	if g.mainOffset > max {
		g.mainOffset = max
	}
}

func (g *GUI) handleStatusKeys(evt terminal.Event) {
	// Nothing special
}

func (g *GUI) handleFilesKeys(evt terminal.Event) {
	navHandled := g.handleListNav(evt, &g.fileIdx, len(g.files))
	if navHandled {
		g.updateMainContent()
		g.dirty = true
		return
	}

	switch evt.Rune {
	case ' ':
		if g.fileIdx < len(g.files) {
			f := g.files[g.fileIdx]
			var err error
			if f.X == '?' || f.Y != ' ' {
				err = g.repo.StageFile(f.Name)
				g.addCommandLog(fmt.Sprintf("git add -- %s", f.Name))
			} else {
				err = g.repo.UnstageFile(f.Name)
				g.addCommandLog(fmt.Sprintf("git reset HEAD -- %s", f.Name))
			}
			if err != nil {
				g.addCommandLog(fmt.Sprintf("Error: %v", err))
			}
			g.refresh()
		}
	case 'c':
		g.promptCommit()
	case 'a':
		_, err := g.repo.RunCommand("add", "-A")
		if err != nil {
			g.addCommandLog(fmt.Sprintf("Error: %v", err))
		} else {
			g.addCommandLog("git add -A")
			g.refresh()
		}
	case 'd':
		if g.fileIdx < len(g.files) {
			f := g.files[g.fileIdx]
			g.showConfirmDialog(
				fmt.Sprintf("Discard changes to %s?", f.Name),
				func() {
					g.repo.RunCommand("checkout", "--", f.Name)
					g.addCommandLog(fmt.Sprintf("git checkout -- %s", f.Name))
					g.refresh()
				},
				nil,
			)
		}
	case 'r':
		g.refresh()
	case ']':
		g.filesTab = (g.filesTab + 1) % 3
		g.dirty = true
	case '[':
		g.filesTab = (g.filesTab + 2) % 3
		g.dirty = true
	}
}

func (g *GUI) handleBranchesKeys(evt terminal.Event) {
	navHandled := g.handleListNav(evt, &g.branchIdx, len(g.branches))
	if navHandled {
		g.updateMainContent()
		g.dirty = true
		return
	}

	switch evt.Rune {
	case ' ':
		if g.branchIdx < len(g.branches) {
			b := g.branches[g.branchIdx]
			g.repo.RunCommand("checkout", b.Name)
			g.addCommandLog(fmt.Sprintf("git checkout %s", b.Name))
			g.refresh()
		}
	case 'n':
		g.promptInput("New branch name", "", func(name string) {
			if name != "" {
				g.repo.RunCommand("checkout", "-b", name)
				g.addCommandLog(fmt.Sprintf("git checkout -b %s", name))
				g.refresh()
			}
		})
	case ']':
		g.branchesTab = (g.branchesTab + 1) % 3
		g.dirty = true
	case '[':
		g.branchesTab = (g.branchesTab + 2) % 3
		g.dirty = true
	}
}

func (g *GUI) handleCommitsKeys(evt terminal.Event) {
	navHandled := g.handleListNav(evt, &g.commitIdx, len(g.commits))
	if navHandled {
		g.updateMainContent()
		g.dirty = true
		return
	}

	switch evt.Rune {
	case ']':
		g.commitsTab = (g.commitsTab + 1) % 2
		g.dirty = true
	case '[':
		g.commitsTab = (g.commitsTab + 1) % 2
		g.dirty = true
	}
}

func (g *GUI) handleStashKeys(evt terminal.Event) {
	g.handleListNav(evt, &g.stashIdx, len(g.stash))
	g.dirty = true
}

func (g *GUI) handleMainKeys(evt terminal.Event) {
	switch evt.Key {
	case terminal.KeyUp:
		if g.mainOffset > 0 {
			g.mainOffset--
			g.dirty = true
		}
	case terminal.KeyDown:
		g.mainOffset++
		g.clampMainOffset()
		g.dirty = true
	}
	switch evt.Rune {
	case 'K':
		if g.mainOffset > 0 {
			g.mainOffset -= 2
			if g.mainOffset < 0 {
				g.mainOffset = 0
			}
			g.dirty = true
		}
	case 'J':
		g.mainOffset += 2
		g.clampMainOffset()
		g.dirty = true
	}
}

// handleListNav handles up/down/j/k navigation for a list
// Returns true if the event was consumed
func (g *GUI) handleListNav(evt terminal.Event, idx *int, length int) bool {
	switch evt.Key {
	case terminal.KeyUp:
		if *idx > 0 {
			*idx--
			return true
		}
	case terminal.KeyDown:
		if *idx < length-1 {
			*idx++
			return true
		}
	}
	switch evt.Rune {
	case 'j':
		if *idx < length-1 {
			*idx++
			return true
		}
	case 'k':
		if *idx > 0 {
			*idx--
			return true
		}
	case '<':
		*idx = 0
		return true
	case '>':
		if length > 0 {
			*idx = length - 1
		}
		return true
	}
	return false
}

func (g *GUI) handleInputKey(evt terminal.Event) {
	switch evt.Key {
	case terminal.KeyEsc:
		g.showInput = false
		g.dirty = true
	case terminal.KeyEnter:
		g.showInput = false
		if g.inputCallback != nil {
			g.inputCallback(g.inputValue)
		}
		g.dirty = true
	case terminal.KeyBackspace:
		if len(g.inputValue) > 0 {
			runes := []rune(g.inputValue)
			g.inputValue = string(runes[:len(runes)-1])
			g.dirty = true
		}
	default:
		if evt.Rune != 0 && evt.Rune >= ' ' {
			g.inputValue += string(evt.Rune)
			g.dirty = true
		}
	}
}

func (g *GUI) handleConfirmKey(evt terminal.Event) {
	switch evt.Rune {
	case 'y', 'Y':
		g.showConfirm = false
		if g.confirmYes != nil {
			g.confirmYes()
		}
		g.dirty = true
	case 'n', 'N':
		g.showConfirm = false
		if g.confirmNo != nil {
			g.confirmNo()
		}
		g.dirty = true
	}
	switch evt.Key {
	case terminal.KeyEsc:
		g.showConfirm = false
		if g.confirmNo != nil {
			g.confirmNo()
		}
		g.dirty = true
	case terminal.KeyEnter:
		g.showConfirm = false
		if g.confirmYes != nil {
			g.confirmYes()
		}
		g.dirty = true
	}
}

func (g *GUI) promptInput(prompt string, initial string, callback func(string)) {
	g.showInput = true
	g.inputPrompt = prompt
	g.inputValue = initial
	g.inputCallback = callback
	g.dirty = true
}

func (g *GUI) showConfirmDialog(msg string, yes func(), no func()) {
	g.showConfirm = true
	g.confirmMsg = msg
	g.confirmYes = yes
	g.confirmNo = no
	g.dirty = true
}

func (g *GUI) promptCommit() {
	g.promptInput("Commit message", "", func(msg string) {
		if msg == "" {
			return
		}
		_, err := g.repo.RunCommand("commit", "-m", msg)
		if err != nil {
			g.addCommandLog(fmt.Sprintf("Error: %v", err))
		} else {
			g.addCommandLog(fmt.Sprintf("git commit -m %q", msg))
			g.refresh()
		}
	})
}

// GetLogFile returns the log file path
func GetLogFile() string {
	home, _ := os.UserHomeDir()
	xdgState := os.Getenv("XDG_STATE_HOME")
	if xdgState == "" {
		xdgState = filepath.Join(home, ".local", "state")
	}
	return filepath.Join(xdgState, "lazygit", "development.log")
}

// stripANSI removes ANSI escape codes
func stripANSI(s string) string {
	var result strings.Builder
	i := 0
	for i < len(s) {
		if s[i] == 0x1b && i+1 < len(s) && s[i+1] == '[' {
			i += 2
			for i < len(s) && s[i] != 'm' && s[i] != 'J' && s[i] != 'H' && s[i] != 'K' {
				i++
			}
			if i < len(s) {
				i++
			}
		} else {
			result.WriteByte(s[i])
			i++
		}
	}
	return result.String()
}

// writeColoredLine writes a line with ANSI codes to the screen
func writeColoredLine(scr *Screen, x, y int, line string, maxW int) {
	col := x
	currentStyle := ""
	i := 0

	for i < len(line) && col < x+maxW {
		if line[i] == 0x1b && i+1 < len(line) && line[i+1] == '[' {
			start := i
			i += 2
			for i < len(line) && line[i] != 'm' {
				i++
			}
			if i < len(line) {
				i++
			}
			seq := line[start:i]
			if seq == Reset || seq == esc+"[0m" {
				currentStyle = ""
			} else {
				currentStyle = seq
			}
		} else {
			r, size := utf8.DecodeRuneInString(line[i:])
			if r == utf8.RuneError && size == 1 {
				r = rune(line[i])
				size = 1
			}
			if r == '\t' {
				scr.SetCell(col, y, ' ', currentStyle)
				col++
			} else if r >= ' ' {
				scr.SetCell(col, y, r, currentStyle)
				rw := RuneWidth(r)
				if rw > 1 && col+1 < x+maxW {
					scr.SetCell(col+1, y, ' ', currentStyle)
				}
				col += rw
			}
			i += size
		}
	}
}
